INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REROUTEPROC', 'Reroute Processors', 'Once per encounter, may take a Reroute Processors action, make an [B]Average ([DI][DI]) Computers check[b] to reduce one of a droid''s characteristics by 1 and increase another of its characteristics by 1.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESOURCEREFIT', 'Resourceful Refit', 'May perform the Resourceful Refit action, make an [B]Average ([DI][DI]) Mechanics check[b] to scavenge an old attachment to construct a new one, reducing its price by that of the dismantled attachment.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
