INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HARASS', 'Harass', 'Whenever the character''s bonded animal makes a successful combat check against a target, it may forgo inflicting damage to upgrade the difficulty of the target''s next check once instead.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
