INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARKDEATH', 'Marked for Death', 'Take the Marked for Death maneuver; committing [FO]. Add [AD][AD] to combat checks against target while [FO] remains committed but cannot use this talent again until the original target is incapacitated or the session ends.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MENACE', 'Menace', 'Enemy within short range of the character''s bonded animal adds [SE] to next Combat check made against the character.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
