INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONENAT', 'One with Nature', 'When in the wilderness, the character may make a [B]Simple (-) Survival check[b] instead of Discipline or Cool to recover strain at the end of an encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
