INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TERRKILL', 'Terrifying Kill', 'The character may spend one Destiny Point to perform a Terrifying Kill maneuver immediately after conducting a successful attack where the target is incapacitated or suffers a Critical Injury (the character must still be able to perform maneuvers, and may not perform more than two maneuvers in a turn). The character rolls Force dice no greater than [their] Force rating, and may spend a Force point to inflict 1 strain on any characters within short range of that target (and may do so multiple times).', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('AMBUSH', 'Ambush', 'Once per round while benefiting from cover, may make the Ambush maneuver. Add damage equal to Stealth skill to one hit of next successful combat check against a target within short range before the end of the turn.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUNNSNARE', 'Cunning Snare', 'Once per encounter as an action, may create a trap. Any other character who moves to engaged range of the trap must make an [B]Opposed Vigilance vs. Survival check[b] to avoid harm and ill effects.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
