INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SEIZEINIT', 'Seize the Initiative', 'Once per session, as a maneuver, may make a [B]Hard ([DI][DI][DI]) Athletics check[b]. On success, other PCs may take their turns immediately. Each PC who acts this way counts as having acted for this round (and thus cannot act again this round. The Initiative order returns to its previous order at the beginning of the next round.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
