INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CRUELCOM', 'Cruel Commander', 'When upgrading the ability of a Mass Combat check in a mass combat in which the character is the commander of the acting force (or when upgrading the difficulty, if the character is the commander of the enemy force), the character may use ranks in Coercion instead of ranks in Leadership.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DROIDCOMM', 'Droid Commander', 'Once per encounter, the character may perform Field Commander as a maneuver instead of an action. All affected allies must be droids.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXEMPREP', 'Exemplar of the Republic', 'When making a Mass Combat check for which the character is the acting commander or takes a prominent role on the battlefield, the character may add [FO] no greater than their Force rating to the check. The character may spend [FP] to add [SU] or [AD] (character''s choice) to the result.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ICHORRES', 'Ichor Reserve', 'Once per session, the character may suffer 2 strain to perform the Ichor Reserve maneuver. Their Force rating increases by 1 until the end of the scene or encounter. At the GM''s discretion, the character may need to occasionally return to Dathomir to replenish their supply of magickal ichor.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWNPROG', 'Known Programming', 'Once per session, make a [B]Hard ([DI][DI][DI]) Vigilance check[b] to upgrade the difficulty of a certain droid model''s check against the character, plus one ally per [SU] after the first, once for the rest of the encounter.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWNPROGIMP', 'Known Programming (Improved)', 'Allies affected by Known Programming also upgrade the ability of their checks targeting the chose droid model once.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWSTR', 'Knowledge is Strength', 'Once per session, when making a check, the character may increase their Force rating by their ranks in Knowledge (Warfare) for the duration of the check. If the rules for Morality in [B]Force and Destiny[b] are in use, a character who has purchased this talent gains 1 Conflict at the beginning of each game session.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LEADBACK', 'Lead From the Back', 'Once per round when an enemy makes a successful combat check targeting the character, the character may spend 1 Destiny Point to perform the Lead from the Back incidental. The character chooses one allied NPC subordinate within short range, who becomes the target of the attack instead. At the GM''s discretion, the character may select an allied NPC at a greater distance if they are between the character and the attacker.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LEADFRONT', 'Lead From the Front', 'After succeeding on a Leadership check or other check to inspire, lead, or rally an audience, the character may spend 1 Destiny Point to upgrade the ability of the next combat check made by each ally within short range once.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATCHAMP', 'Natural Champion', 'Once per game session, the character may reroll any one Leadership or Lightsaber check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOBFOOLIMP', 'Nobody''s Fool (Improved)', 'When targeted by a Charm, Coercion, or Deception check, the character may spend [DE] or [TH][TH][TH] from the check to inflict strain on the opponent equal to the character''s ranks in Nobody''s Fool.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TACTPLAN', 'Tactical Planning', 'Once per session, the character may substitute a Knowledge(Warfare) skill check for another skill check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ALTDEAL', 'Altered Deal', 'Once per Session, the character may take the Altered Deal action and make a [B]Hard ([DI][DI][DI]) Coercion check[b] to radically change a previously agreed upon deal or bargain to a version much more advantageous to the character.  The player player must narratively explain what happened, including the details of how the character arranged for the deal to be changed as well as the specifics of the new deal.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASFORCEWILLS', 'As the Force Wills It', 'May make an [B]Easy ([DI]) Knowledge (Lore) check[b] to heal strain at the end of an encounter. [TR] can be spent to heal all strain.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BYBOOK', 'By the Book', 'Once per encounter before making a combat check, the character may suffer two strain to add [AD] to the results equal to his ranks in By the Book.', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMARMS', 'Comrades in Arms', 'Once per encounter, the character may take a Comrades in Arms action to make a [B]Hard ([DI][DI][DI]) Discipline check[b].  If successful, the character plus one ally per [SU] within medium range gains +1 defense for the remainder of the encounter.  Should an ally move outside of medium range, that ally loses this benefit.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUNNINGSTUNT', 'Cunning Stunt', 'Use Cunning instead of Presence for Cool checks.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISCLORE', 'Disciple of Lore', 'Once per round, may suffer 1 strain to decrease the difficulty of next Knowledge (Lore) check a number of times equal to ranks in Disciple of Lore.', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISCSOUL', 'Disciplined Soul', 'The character may spend one Destiny Point after making a Discipline check to spend a number of [TH] not exceeding the character''s ranks in Knowledge (Lore) as [AD].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISSTRIKE', 'Disorienting Strike', 'After failing a Lightsaber combat check, may spend [AD][AD] or [TR] to disorient opponents for three rounds.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DOUBLETALK', 'Double-Talk', 'The character may spend [AD][AD] or [TR] from a successful Charm or Deception check to disorient a number of opponents within short range equal to his Presence for remainder of round and next two rounds.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXTREACH', 'Extended Reach', 'While armed with a two-handed melee weapon, may suffer one strain to make a Melee combat check with that weapon targeting an enemy at up to short range (rather than engaged range).', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEARREP', 'Fearsome Rep', 'Add automatic [AD] to the results of Coercion checks equal to ranks in Fearsome Rep.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINESSE', 'Finesse', 'Use Agility instead of Brawn for Brawl or Melee checks.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPCOMARMS', 'Comrades in Arms (Improved)', 'Spend [AD][AD][AD] or [TR] from Comrades in Arms check to also gain +1 soak or give one affected ally +1 soak.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPSECRETJEDI', 'Secrets of the Jedi (Improved)', 'Discipline becomes a career skill. Secrets of the Jedi may also be used when installing mods on melee weapons.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWENEMY', 'Know the Enemy', 'The character may use Knowledge (Warfare) skill when making checks to determine Initiative.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWROPES', 'Knows the Ropes', 'Add [BO] to checks made to escape from restraints equal to ranks in Knowledge (Underworld). Spend [TR] to free all other allies withing short range.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERSTARGET', 'Persistent Targeting', 'After making one or more successful combat checks against a target, add [BO] to combat checks against that same target for the remainder of the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PREPBOARD', 'Prepare to be Boarded!', 'Once per encounter may take Prepare to be Boarded! action and make [B]opposed Coercion vs. Discipline check[b] against enemy ship captain. If successful, the enemy suffers 1 strain per uncanceled [SU] and surrenders ship if he exceeds strain threshold. May also spend [TR] or [AD][AD][AD][AD] to inflict strain equal to ranks in Coercion.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PUSHASIDE', 'Push Aside', 'After making a successful Melee, Brawl, or Lightsaber combat check against an engaged foe, may force the foe to move to short range in a direction of the opponent''s choosing. Spend [TR] to cause the opponent to fall prone after moving.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SEENTHINGS', 'Seen A Lot of Things', 'Whenever the character fails a Knowledge check, he may spend [AD][AD][AD] to roll the check again during his next turn.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STEADYAIM', 'Steady Aim', 'The character does not lose the benefits of the Aim maneuver if he performs other maneuvers (including moving) or actions. He does lose the benefits of the Aim maneuver if the encounter ends.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TARGFIRE', 'Targeted Firepower', 'Once per session may take Targeted Firepower action; identify one enemy target and make a [B]Hard ([DI][DI][DI]) Knowledge (Warfare) check[b]. If successful, for the rest of the encounter allies within short range of character add [AD] to attacks against target equal to [SU] gained in the check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TENACIOUS', 'Tenacious', 'Upgrade the number of advantages needed to score a critical hit
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRUSTNO', 'Trust No One', 'When targeted by a social check, may choose to suffer one strain to add automatic [FA] to the check. If the check fails with [DE], the character may immediately perform a maneuver as an out-of-turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MADMAI', 'Madcap Maintenance*', 'Once per session, may reroll one check to repair or maintain. If the rerolled check succeeds, add [TR] to the next check made using the item. Otherwise, the item becomes damaged further.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASQULA', 'Ask Questions Later', 'Once per encounter as an out-of-turn incidental, before the character or an ally makes a social check, add [AD], [SU], or [TR] to that check, determined by the strongest type of adversary defeated during the current encounter: [AD] for a minion, [SU] for a rival, [TR] for a nemesis.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHFR', 'Shoot First', 'Once per session when a foe would attack, spend a Destiny Point to make a Ranged (Light) attack against that foe before they act as an out-of-turn incidental. They are considered to have not yet acted this round.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPITIMP', 'Guns Blazing (Improved)', 'Once per round after making a successful two-weapon Ranged (Light) attack, suffer 3 strain to assign an additional hit from either weapon to a target within range.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRSH', 'Trick Shot', 'The character removes [SE][SE] imposed on Ranged (Heavy) or Ranged (Light) checks due to their target''s cover or from the aim maneuver. Additionally, the character may make Ranged (Heavy) and Ranged (Light) attacks targeting foes for which they lack line of site, per GM discretion.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DANGDEV', 'Dangerous Development*', 'When making a check to improve or craft an item, may suffer 2 strain and upgrade the check once. On [SU], may add a single permanent improvement to the item.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EURE', 'EUREKA!*', 'Once per session, may spend strain equal to difficulty of a successful Intellect check to add a [TR] to that check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SME', 'SME*', 'Once per encounter, may spend 1 Destiny point to add [BO] [BO] [BO] to any check the character makes to which their personal experience is relevant.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REVEG', 'Reverse Engineering*', 'Once per session, the character may spend credits and make a [B]Knowledge (Education)[b] or [B]Mechanics check[b] to create an identical copy of a piece of personal gear the character has access to. The difficulty of this check is equal to half the rarity of the item, rounded down, and the time required is 2 hours times the difficulty. The credit cost of this process is equal to half of the item''s base price.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SYNTH', 'Synthesis*', 'Once per encounter, may make a [B]Hard ([DI][DI][DI]) Medicine check[b] to create a chemical equivalent to any medical supply or chemical compound with a rarity of Intellect + [SU] or lower. The character may spend [AD][AD] to create an additional unit per [AD][AD] spent.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TECBAB', 'Technobabble*', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Knowledge (Education) check[b] to establish a fact that solves a current problem.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HIDFEA', 'Hidden Feature*', 'Once per session as an incidental, while the character is aboard a vessel they created or are intimately familiar with, they may activate a previously unknown minor feature of the vessel as if a Destiny Point had been spent, per GM discretion. This feature lasts until the end of the encounter. At any future point, any character may reactivate this feature by spending a Destiny point.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVBATT', 'Overcharged Battery*', 'Once per round while piloting or operating a starship, before the character or an ally makes a Gunnery check, may have the starship suffer 2 system strain to increase the damage of the attack by 2 or reduce the Critical Rating by 1 (minimum of 1).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('AGAODD', 'Against The Odds*', 'Add [BO] per rank of Against The Odds to [B]Daunting[b] or harder checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKITINT', 'Let’s Make It Interesting*', 'Once per session after making a successful check to wager or gamble, spend a Destiny Point to have a loser substitute or supplement a narrative or material reward of the character''s choice, instead of only credits. The reward is per GM discretion.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKLUCK', 'Make Your Own Luck*', 'Once per session, make a [B]Hard ([DI][DI][DI]) Cool Check[b]. On success, allies equal to ranks of Cool may reroll 1 positive die on the next check they make, plus one additional die for every [SU][SU] past the first. Spend [AD][AD] or [TR] to allow one of those allies to reroll positive or negative instead.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REVFOR', 'Reversal of Fortunes*', 'Once per session, after the character makes a check resulting in [DE],  spend 1 Destiny Point to cancel a [DE] result and add a [DE] to the next check made by an adversary in the scene. How the character turned their misfortune around is per GM discretion.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RAISSTAK', 'Raise The Stakes*', 'Once per check, the character may suffer 2 strain to increase and upgrade the difficulty of their next check once. If successful, add [AD] equal to the final difficulty of the check to the results.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RAISTAIMP', 'Raise The Stakes (Improved)*', 'Double the number of [TR] and [DE] results on checks affected by Raise The Stakes, regardless of Success.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KILKINIMP', 'Kill With Kindness (Improved)*', 'Once per encounter, make a [B]Hard ([DI][DI][DI]) Charm[b] or [B]Leadership check[b]. On success, a number of characters equal to the character''s ranks of Kill With Kindness add [AD] or [TH] to checks they make this encounter, chosen separately for each character. Spend [TR] to double the number of [AD] or [TH] added this way.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HAPPHELP', 'Happy to Help*', 'When providing or accepting assistance, add [BO] to the check in addition to the normal effects of assistance.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HAPHELIMP', 'Happy to Help (Improved)*', 'Once per encounter, when assisting or being assisted, may choose to have Happy To Help add [SU] to the check instead of [BO].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BYPSECIMP', 'Bypass Security (Improved)*', 'May spend [AD][AD][AD] or [TR] from checks to unlock doors or disable a security device to add [BO] equal to ranks of Bypass Security to similar checks in the same system or location this session.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DECOY', 'Decoy*', 'Once per session, spend a Destiny Point to produce a facsimile of an encumbrance 1 or smaller item in the scene. Any character attempting to determine that it is counterfeit must make an [B]opposed Perception vs. Skulduggery check[b].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DIRTTRIC', 'Dirty Tricks', 'Once per session, make a [B]Hard ([DI][DI][DI]) Skulduggery check[b] to add [SE] equal to [SU] to the next check made by a number of enemies equal to the character’s ranks of Cunning.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXITSTRA', 'Exit Strategy*', 'Once per session, make a [B]Hard ([DI][DI][DI]) Vigilance check[b] to notice a discreet path of egress. On success, add [BO] to all checks the character or allies with medium range make to leave the encounter. This includes attacks against characters who intentionally impede their escape.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FADEAWAY', 'Fade Away*', 'Once per encounter, when targeted by a combat check, spend a Destiny Point to add [SE] equal to the character''s ranks in Stealth. If that attack fails, the character may not be targeted by attacks until the beginning of their next turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STAKEOUT', 'Stakeout', 'Once per session, make a [B]Hard ([DI][DI][DI]) Cool[b] or [B]Skulduggery check[b] while surveilling a person or place.  For the remainder of the session, add automatic [AD][AD] to checks they make that are associated with that location or person.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANIMCOMP', 'Animal Companion', 'Choose an animal no larger than Silhouette 2 to be an Animal Companion. Upgrade all checks made to soothe or heal them once.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANCOIMP', 'Animal Companion (Improved)', 'Animal Companion may now be no larger than Silhouette 3. Attacks targeting an Animal Companion treat their critical rating as 1 higher.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BRTHIN', 'Break Them In', 'Make a [B]Hard ([DI][DI][DI]) Athletics check[b] to train one or more animals, upgrading the difficulty by the Animal’s Willpower. On success, one animal gains Trained Mount 1 until the end of the session, plus 1 animal per additional [SU][SU].', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTRID', 'Master Rider', 'Once per turn while mounted, may suffer 2 strain to perform a Survival Check or other mount-handling action as a maneuver.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RIDDOW', 'Ride Down', 'While mounted, the mount’s Brawl attacks and any rider’s melee attacks deal additional damage equal to the speed of the mount.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRUSCOMP', 'Trusty Companion', 'Once per session when successfully attacked, the character may spend 1 Destiny Point and perform the Trusty Companion out-of-turn incidental to have an Animal Companion within medium range move to the character and become the target of the attack instead. 
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WILYRIDE', 'Wily Rider', 'Count mounted animals as having a silhouette as 1 lower when being attacked. Minimum of 0.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WRANGLE', 'Wrangle', 'Once per round, the character may suffer strain up to ranks in Athletics and perform the Wrangle maneuver. An animal or foe within short range adds [SE] equal to strain suffered to their next action and treats their surroundings as difficult terrain until the character’s next turn. [TH][TH] from checks made by the wrangled foe while wrangled may be spent to knock the foe prone, and [TH][TH][TH] or [DE] may be spent to Immobilize them for rounds equal to the character''s ranks of Athletics. The character must have rope or a similarly-functioning item or short-range melee weapon to perform the Wrangle maneuver.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ATTVEC', 'Attack Vector', 'Once per encounter, may Make a [B]Hard ([DI][DI][DI]) Perception check[b] to identify a weak point in an enemy vehicle or structure. On success, aim maneuvers made to target it before the end of the character’s next turn add [SU] in addition to normal effects.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMBARMS', 'Combined Arms', 'Allied characters within short range of a vehicle piloted by the character treat their ranged defense as equal to the highest defense zone of that vehicle.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIRSUPIMP', 'Fire Support (Improved)', 'After making a successful attack, may spend 1 Destiny Point to extend the benefit of Fire Support to all allies within planetary close range.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONEINAMIL', 'One in a Million', 'Once per session, when inflicting a critical hit, may suffer 3 strain to change the result to any [B]Hard ([DI][DI][DI])[b] Critical Hit.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRIGDISC', 'Trigger Discipline', 'When making a ranged attack, the character may suffer 2 strain to remove a number of [BO] up ranks of Discipline from the dice pool, adding [AD] to the pool for each removed this way.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUSTFIRE', 'Sustained Fire', 'When performing an Aim maneuver, if the character successfully attacked the target this or last round, upgrade the ability of that attack instead of the aim’s normal effects (cannot be used to target a specific item or part of the target).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTMISS', 'Master Missileer', 'Before rolling a [B]Guided[b] attack, may suffer strain up to ranks of the weapon’s combat skill to upgrade the ability of the [B]Guided[b] roll that many times.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WEAPFREE', 'Weapons Free', 'Once per encounter, as a maneuver, may ignore a weapon’s [B]Slow-Firing[b] quality this turn and upgrade the difficulty of the next check using it equal to its ranks of [B]Slow-Firing[b].', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MANUOVER', 'Manual Override', 'Once per encounter while piloting a silhouette 4 or smaller starship or vehicle that has exceeded its system strain threshold, the character may make a [B]Daunting ([DI][DI][DI][DI]) Coordination check[b] to set the system strain to its threshold and set the vehicle''s speed to the last speed it had before exceeding the threshold. The character may spend [AD][AD] to reduce the number that the craft’s system strain is set to by 1 for each [AD][AD] spent, and may spend [TR] to immediately take another action.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PLAMAISYS', 'Planned Maintenance System', 'Repairs made to Signature Vehicle cost 25% less per rank of Planned Maintenance System, rounded down.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIGVEHSUP', 'Signature Vehicle (Supreme)', 'Once per session, may spend 1 Destiny Point to add [TR] to a check involving the Signature Vehicle as an out-of-turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNAUREQU', 'Unauthorized Requisition', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Knowledge (Underworld) check[b] to establish ill-gotten munitions or equipment in their ship or base, with a cost no greater than 250 credits per rank of Knowledge (Society). The item(s) must be contraband or stolen.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CORSLIIMP', 'Corellian Slip (Improved)', 'Spend [TH][TH][TH] or [DE] from attacks targeting the character or an ally within close range benefitting from Evasive Maneuvers to inflict a hit on the attacker.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BREOFF', 'Break Off', 'Once per encounter, when an allied vehicle within close range becomes the target of an attack, may make a [B]Hard ([DI][DI][DI]) Vigilance check[b] to become the target of the attack. The character may spend [AD][AD] to upgrade the difficulty of the attack once, and may spend [TR] to have the original defender of the attack Gain The Advantage on the attacker.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CORESLIP', 'Corellian Slip', 'When the character performs the Evasive Maneuvers maneuver, a number of allied vehicles equal to ranks in Vigilance and within close range also gain the benefits of the maneuver. These allied vehicles maintain the benefits until they leave close range with the character or the character loses the benefits of Evasive Maneuvers.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MATHSPEE', 'Match Speed', 'Once per round when an ally within close range performs the Accelerate/Decelerate, Fly/Drive, or Punch it maneuver, may suffer 2 strain to perform the same maneuver to follow that ally as an out-of-turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASSASSIN', 'Assassinate', 'When inflicting a critical injury on a minion group, if undetected by them, may spend additional [AD] to remove an additional member per [AD] spent. A character is considered to be undetected by a foe if they aren’t aware of their general or specific location, and aren’t on alert to their presence, before the attack. A Game Master may determine that even when generally alerted, a character is still undetected until they either attack again or reveal themself visually.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASSASIMP', 'Assassinate (Improved)', 'Before rolling a combat check while undetected by the target, suffer strain up to [BO] in pool to trade that many [BO] for that many [AD]. Assassinate may remove a Rival by spending [AD][AD][AD] or [TR].
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FROMSHAD', 'From the Shadows', 'While undetected by enemies, the character may use the Stealth Skill when making checks to determine initiative.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOWITNES', 'No Witnesses', 'Once per encounter, after incapacitating an enemy, may make a [B]Hard ([DI][DI][DI]) Stealth[b] check. On success, they are undetected as the attacker. May spend [AD] to move one range band per [AD] spent, and may spend [TR] to escape the scene completely.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PREAIMIMP', 'Precise Aim (Improved)', 'When using Precise Aim, all non-Gunnery attacks made by the character this round have their Pierce rating increased by ranks in Precise Aim.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERFCRIM', 'The Perfect Crime', 'Once per session may make a [B]Hard ([DI][DI][DI]) Skulduggery check[b] to reveal how a previously unknown plan assists them in a crime or attack during this scene. The nature of the revelation is ultimately subject to the GM’s discretion, but they should give a significant advantage to the PCs. If the check fails and generates a [DE], however, the GM may decide that the character’s plan goes seriously awry.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ALWAPREP', 'Always Prepared', 'Once per session, as an incidental, produce a previously undocumented piece of personal equipment or weapon, with a rarity no greater than 4, as if a Destiny Point was spent. If producing a weapon, it also has the Limited Ammo 1 quality.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASOFARM', 'Master of Arms', 'Once per encounter, make a [B]Hard ([DI][DI][DI]) Mechanics[b] check. On success, a weapon quality (excluding Breach, Concussive, and Linked) of a weapon within engaged range has its rating increased by 2 until the end of the encounter. The GM may spend [DE] to have an affected weapon malfunction at the end of the encounter; it is considered broken until the character spends six hours making an [B]Average ([DI][DI]) Mechanics check[b] to repair it.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASARMIMP', 'Master of Arms (Improved)', 'Once per encounter, when using the Master of Arms action, spend [AD][AD] or a [TR] to immediately take an additional action.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASARMSUP', 'Master of Arms (Supreme)', 'When making the Master of Arms action, the character may choose any number of additional weapons to increase an existing quality’s rating of each of those weapons by 2, and may choose a different quality for each affected weapon. If they do, upgrade the difficulty once for each chosen weapon beyond the first. Each of the chosen qualities cost one less [AD] to activate, to a minimum of 1.  Qualities that do not have a rating, such as Auto-Fire, are not applicable for the reduction.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TARGACQU', 'Target Acquired', 'Take the Target Acquired Action, make an [B]opposed Coercion check[b] against an adversary within Medium Range. On Success, immobilize that adversary until the end of the next round. Spend [AD][AD] to effect an additional foe within medium range. When spending [AD] to affect additional targets, the additional targets must be of an equal or lesser adversary tier.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TARACQIMP', 'Target Acquired (Improved)', 'When taking the Target Acquired Action, the character adds [BO] per status effect affecting the target. Spend [TR] generated on the check to Stagger an affected adversary. Disorient, Burn, Prone, Immobilized, Staggered, and suffering from Crippling Blow are all status effects, but this list is not exhaustive, and GMs should include other non-named effects.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EYEOSTOR', 'Eye of the Storm', 'Perform the Eye of the Storm maneuver, suffer 1 strain, to make next Brawl attack this turn gain the [B]Blast[b] quality with a rating equal to ranks of Brawn plus ranks of Discipline. Blast triggered on this attack only affects foes.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARTPROW', 'Martial Prowess', 'When making a combat check, may suffer 2 strain to substitute Athletics for Melee, or Coordination for Ranged (Light or Heavy).', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNAPARIMP', 'Unarmed Parry (Improved)', 'Whenever an enemy engaged with the character makes a combat check, after the attack is resolved, the character may spend [TH][TH][TH] or [DE] results to disarm the attacker, and may gain control of the used weapon. If not equipping the weapon, it falls within short range at a location of the player''s choice.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PREPTURB', 'Prepare for Turbulence', 'Once per encounter, make a [B]Hard ([DI][DI][DI]) Astrogation[b] check. On success, the character notices or navigates towards a moderate navigation hazard at close range. Spend [AD][AD][AD] or [TR] for a severe navigation hazard.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SMOOOPER', 'Smooth Operator', 'After making a successful Gunnery attack, spend a Destiny Point and suffer strain no greater than [SU] to convert that many [SU] to [AD].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RELENTLESS', 'Relentless', 'Suffer a number of strain to downgrade the difficulty of checks to chase, track, or tail a target by an equal number. Strain suffered this way cannot exceed ranks of Relentless.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STAKEIMP', 'Stakeout (Improved)', 'When using the Stakeout action, may spend [AD] to extend this benefit to 1 ally per [AD] spent, and may spend [TR] to add [SU] to 1 ally''s checks.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ULTIMATUM', 'Ultimatum', 'Once per encounter, may make an opposed [B]Negotiations vs. Cool[b] check to add [SU] to each check made to attack or subdue the target. Spend [AD][AD][AD] or [TR] to affect an additional target.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CRASHTHRO', 'Crash Through', 'When instigating a collision with another vehicle, add +10 for each point of Armor of the character’s vehicle to the other vehicle’s resulting critical hit.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXPTRAIMP', 'Expert Tracker (Improved)', 'Once per session, the character may make the Improved Expert Tracker action; Make a [B]Formidable ([DI][DI][DI][DI][DI]) Survival[b] or [B]Perception[b] to find a minor item lost by a tracked target. Decrease the Difficulty once per rank of Expert Tracker. On a successful check, spend [TR] to find a Major item instead. An example of a minor item is like an identifying accessory or some material indicating previous location or mode of travel. Examples of Major items could be an item like a sentimental or “quest item” that the target may not want to leave the vicinity without recovering, or an item like a weapon that may inhibit their combat effectiveness due to having lost.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GATHERER', 'Gatherer', 'When foraging for food, water, or shelter, the character may choose to add [BO] or remove [SE] from the check per rank of Gatherer.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWPREY', 'Know Your Prey', 'Once per encounter make a [B]Hard ([DI][DI][DI]) Knowledge (Xenology)[b] check to add [SE][SE] to all checks that target or are opposed by the character for the remainder of this encounter. Spend [AD] to extend that benefit to one ally per [AD] spent, and [TR] to upgrade the difficulty of those checks once.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LANDPROV', 'The Land Provides', 'Once per session, make a [B]Hard ([DI][DI][DI]) Survival check [b]to fashion a low-tech solution to a current problem using nearby forageable materials. This solution or object must be approved by the GM, who may impose negative qualities like Inferior or Limited Ammo, and functions until the end of the encounter.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATUCAMO', 'Natural Camouflage', 'When making a stealth check in natural environments, suffer two strain to substitute Survival for the required skill.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOISSAFE', 'Nowhere is Safe', 'May spend [AD][AD] or [TR] from a non-vehicle or starship attack to reduce the target’s defense by a number equal to ranks in Perception until the end of the character’s next turn', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOSAFIMP', 'Nowhere is Safe (Improved)', 'After making a successful attack against a defenseless target, may suffer 3 strain to add [TR] to the check. A character is considered defenseless if they have no defense rating against the attack.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HIREHELP', 'Hired Help', 'Once per Encounter, the character may take the Hired Help action; they make an [B]opposed Negotiation vs Discipline check[b] targeting a minion group or Rival within Medium range. On success, they work towards the character''s goals until the end of the encounter. The character must pay a minion group whose services are bought this way 100 credits per minion in the group, or 500 credits for a Rival. The task they are directed to perform must not violate common sense, their core values, or be obviously suicidal. The Game Master ultimately has control of the NPC(s), and determines the bounds of their support.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HIRHELIMP', 'Hired Help (Improved)', 'Once per encounter, may spend 1 Destiny Point to have engaged Hired Help take a successful hit on the character instead, or take responsibility for something the character did.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HIRHELSUP', 'Hired Help (Supreme)', 'The Hired Help action may now target enemy Minions and Rivals. The credit price to target them is doubled.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GREPALIMP', 'Greased Palms (Improved)', 'Once per session, may reroll a social check by paying credits equal to 100 times the difficulty of the check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOUINVIMP', 'Sound Investments (Improved)', 'At the beginning of each session, may invest all Sound Investment credits and make a [B]Formidable ([DI][DI][DI][DI][DI]) Knowledge (Core Worlds)[b] or [B]Knowledge (Underworld) check[b], decreased by ranks of Sound Investments, to gain a return on the investment. On [SUCCESS], gain 100 additional credits plus 10% of the initial investments for each [SUCCESS] past the first. On [FA], lose half of the initial investment. [TRIUMPH] may be spent to double the number of successes on a successful check, or recover 75% of initial investment on a failed check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MERCSHOT', 'Merciful Shot', 'Before making a non-Gunnery ranged attack, may suffer 2 strain to inflict damage as strain instead of wounds. If using a weapon with the Stun Damage quality or using the Stun Setting, add [BO][BO].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MERSHOIMP', 'Merciful Shot (Improved)', 'When inflicting damage from non-gunnery ranged attack as strain damage, may spend  [AD] [AD] [AD] or [TR] to [I]Stagger[i] or [I]Immobilize[i] the target.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REFORSKY', 'Reach For the Sky', 'Once per encounter, make a [B]Hard ([DI][DI][DI]) Coercion[b] or [B]Leadership check[b]. A number of characters equal to Willpower suffer 1 strain when they perform a maneuver this encounter. Spend [TR] to force a character to perform a move maneuver.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTMANI', 'Master Manipulator', 'Once per round, suffer 2 strain to perform a social check as a maneuver.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PULLSTRI', 'Pulling Strings', 'Once per Session, make an opposed Social check to compel the target to perform a minor favor this session. Add [TR] to one check associated with this favor.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SKILORAT', 'Skilled Orator', 'Once per round, may spend [TR] from a social check to affect twice the number of targets, or have each target recover or suffer twice the number of strain.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WELLCONN', 'Well-Connected', 'Once per Session, the character may reveal a contact who can provide access to a person, location, or resource. When the character does this, they must explain how they know this contact and what their connection is to the desired person, location, or resource. They should be open to helping the players, but the Game Master determines their potential cost, in credits, material, labor, informal promises of future favors, or formal Obligation.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('AUTHSUBJ', 'Authority On The Subject', 'Once per encounter when a foe would make a check, may spend 1 Destiny Point to establish a fact and treat the check as opposed by the character’s most appropriate Knowledge Skill.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASTOBSIMP', 'Astute Observation (Improved)', 'Once per session, if an ally would fail a check, may spend 1 Destiny Point to roll a [B]Perception check[b] using the original difficulty, if successful, the ally''s check succeeds with the same results as the Perception check.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('QUICSTUD', 'Quick Study', 'When making a skill check with an unranked skill, may suffer a number of strain to add an equal number of [BO] to the check. Strain suffered this way cannot exceed ranks in Quick Study.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNQUAUTH', 'Unquestioned Authority', 'Remove [SE] from Coercion and Leadership checks equal to ranks of Unquestioned Authority.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMERBULK', 'Emergency Bulkheads', 'Once per session, when the Flagship would suffer a critical hit, may take an Emergency Bulkhead incidental; make a [B]Hard ([DI][DI][DI]) Education check[b] to stop the vessel from suffering  the critical hit. If successful, the Command Ship does not suffer the Critical Hit and does not suffer any of its normal effects (but the attack that causes the critical hit still deals damage as normal).', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FLAGSHIP', 'Flagship', 'Choose one starship as their Flagship. Upgrade the ability of fear checks made by crew on the Flagship once', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FLASHIIMP', 'Flagship (Improved)', 'When the character performs the assist maneuver aboard their Flagship, upgrade the ability of the check once, in addition to normal effects of assistance.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FLANSPEE', 'Flank Speed!', 'Once per encounter, may perform the Flank Speed! maneuver. The Flagship may perform two pilot-only maneuvers this round and the following round.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PORTCALL', 'Port of Call', 'The Flagship has a dockyard, station, or other location they call home. Add [SU][AD] to all checks made to repair or resupply the Flagship at the Port of Call. If the Port of Call is ever conquered or closed to the character, a new Port of Call may be selected by making a [B]Hard ([DI][DI][DI]) Knowledge (Core World), (Outer Rim), (Underworld)[b], or [B](Warfare) check[b], depending on the nature of the location, and must be properly equipped and prepared, the time required for which is determined by the GM.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RECKREPO', 'Reckless Reposition', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Astrogation check[b]. On success, before a foe begins their turn or makes an attack, the character may have their vessel suffer system strain equal to its silhouette to microjump away as an out-of-turn incidental. At the beginning of the character''s next turn, they may jump again to return no closer than long range from the original location as an incidental. The game Master may spend [TH][TH][TH] or [DE] from the check to choose the final location of the vessel instead.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RECREPIMP', 'Reckless Reposition (Improved)', 'May spend [AD][AD] or [TR] from Reckless Reposition to allow a close-range allied ship to jump with them, which may choose to stay outside the fight, or return with them.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TAKEFEW', 'Take A Few With Us', 'When aboard the Flagship, Fire Discipline affects twice the number of attacks, and those attacks reduce their critical rating by 1, (minimum of 1). When the Flagship has suffered hull trauma greater than half of its threshold, attacks made by it gain Breach +1.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNDERADA', 'Under The Radar', 'While their vessel is in difficult terrain, or is otherwise able to be obscured from enemies, the character may take the Under the Radar action to reduce the emissions of theirs and allied vessels at close range. For rounds equal to the character''s Intellect rating, the character''s vessel and allied vessels within close range go undetected by foes unless a foe makes an [B]opposed Perception vs Computers (Sysops) check[b], adding [BO] to the check for each ally included. Any vessel that exceeds speed 1, attacks, or engages in excessive systems use ends this effect for that vessel.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CEASFIRE', 'Ceasefire', 'Once per session, when leading armed conflict or mass combat, may make an opposed [B]Negotiation vs Cool[b] check targeting the opposing leader. On success, the leaders in the conflict agree to pause hostilities. Add [DE] to first combat check made by an involved character until the end of the following round. Spend [AD][AD][AD] to extend the Ceasefire an additional round, and spend [TR] to exempt allied characters from the effect.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIGURWAR', 'Figure of War', 'The Inspiring Figure incidental may be used to re-roll a failed Mass Combat check as if it were an ally''s check. If a re-rolled Mass Combat check is successful, add [TR] to the check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSPFIGU', 'Inspiring Figure', 'Once per session, suffer 4 strain to allow an ally within medium range to reroll a failed check.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIGHTHRO', 'Fight Through It!', 'Once per encounter, when an ally would exceed one of their thresholds, may make a [B]Hard ([DI][DI][DI]) Coercion check[b] to set their wounds or strain to 1 below its threshold.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RETUFIRE', 'Return Fire!', 'Once per round, when an enemy incapacitates or inflicts a critical injury upon an ally within short range, suffer 3 strain to inflict a hit on that enemy with an equipped weapon.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STERMENT', 'Stern Mentor', 'Once per Encounter, may make a [B]Hard ([DI][DI][DI]) Coercion check[b]. On success, allies equal to Willpower rating may suffer 2 strain and decrease the difficulty of their next check once.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ATTADELT', 'Attack Pattern Delta', 'May make an [B]Average ([DI][DI]) Leadership check[b] to have other allied vehicles up to ranks of Leadership within close range benefit from the character''s ranks of Defensive Driving.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WINGCOMM', 'Wing Commander', 'While piloting a starship or vehicle, the character and allies within close range may spend [AD][AD] or [TR] from checks to determine initiative to perform a pilot-only maneuver as an out of turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HALFBATT', 'Half The Battle', 'Once per session, may spend 1 Destiny Point to add [SE] equal to ranks of a Knowledge skill to any check. If that check fails, add [DE] to the results. The player must state the knowledge they possess which will be their adversary’s undoing.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('THOASSIMP', 'Thorough Assessment (Improved)', 'When distributing a [BO] from Thorough Assessment, may choose to distribute a [SU] instead.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ELEMSUPR', 'Element of Surprise', 'May spend [TR] from checks to determine initiative to force one enemy to use the last available initiative slot this encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COUNOFFE', 'Counteroffensive', 'Once per round, may spend [TH][TH][TH][TH] or [DE] from a foe’s combat or Leadership check to make a Leadership Check as an out-of-turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KILLZONE', 'Killzone', 'Once per session when holding a defensible position, may make a [B]Hard ([DI][DI][DI]) Survival check[b]. On success, foes within medium range add [TH] to all checks for rounds equal to ranks of Cunning.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KILZONIMP', 'Killzone (Improved)', 'The range of Killzone is extended to long range, and foes treat the area as difficult terrain. May spend[AD][AD][AD][AD] or [TR] to add [FA] to all affected checks as well.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CLEAROOM', 'Clear The Room', 'Make a [B]Hard ([DI][DI][DI]) Coercion[b] or [B]Deception check[b] to convince bystanders equal to Willpower to depart quietly. If interrogated about the matter later, these NPCs deny having seen anything or have forgotten anything of importance. The Game Master may determine a minion group acts as a single character for the purposes of this talent.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KINGMAKE', 'Kingmaker', 'Once per encounter, an ally may spend [AD][AD][AD][AD][AD] or [TR] from a social check to treat their rating in the associated characteristic as if it were 1 higher until the end of the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('READROOM', 'Read The Room', 'Once per encounter, may make an [B]Average ([DI][DI]) Vigilance check[b]. On success, gain social insight into one character per [SU], and spend [AD][AD] to add [BO] to all social checks made by you and allies targeting one of those characters. For each character, the player learns which social skill will be most effective against them, or which social skill they are most likely to employ, but not both.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SETTONE', 'Set The Tone', 'Once per encounter, make a [B]Hard ([DI][DI][DI]) Negotiation check[b], and choose two social skills. Decrease the difficulty (minimum [B]Easy ([DI])[b]) of all checks made by others using the first and increase those using the second this encounter.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FRIEEVER', 'I Have Friends Everywhere', 'Once per session, may perform a [B]Hard ([DI][DI][DI]) Streetwise check[b]. On Success, the character chooses an NPC in the scene, or reveals a previously unknown NPC; that NPC is sympathetic to the character''s cause and performs a favor for the character. This favor may be rebellious in nature and may result in legal scrutiny and consequence, but must not be obviously suicidal. The Game Master determines if an NPC cannot be considered sympathetic.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASKMOVE', 'Mask The Movement', 'May make a [B]Hard ([DI][DI][DI]) Deception check[b] to cover the character or allies’ involvement in a crime or dissident activity, adding [FA] plus [FA] for each [SU][SU] past the first to all checks to investigate the offense this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RIGHANGE', 'Righteous Anger', 'The character may suffer 2 strain to make a Leadership check with Willpower instead of Presence.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPARREBE', 'Spark of Rebellion', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Coercion check[b] to cause a number of beings equal to ranks of Coercion plus Willpower to become rebellious until the end of the encounter, and may spend [AD][AD] to guide their general goal. This could be due to something the character did or said, or just because the beings were already unhappy with their position.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPAREBIMP', 'Spark of Rebellion (Improved)', 'Double the number of characters affected by Spark of Rebellion. Spend [AD][AD][AD][AD] or [TR] to affect all rebel-sympathetic characters instead.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TOOLREBE', 'Tools of Rebellion', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Knowledge (Underworld)[b] or [B]Knowledge (Warfare) check[b]. On Success, an amount of weapons and equipment suitable to outfit allies equal to [SU] is covertly stashed nearby.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACALLAID', 'A Call For Aid', 'Once per session, the character may make a [B]Hard ([DI][DI][DI]) Charm check[b]. On success, the character reveals how a previously unknown call for aid has a meaningful impact on the scene. If the check fails and generates a [DE] result, however, the GM may decide that the character''s ineffective plea either puts them in further danger, or the intended ally is apprehended when answering the call.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ESCACLAU', 'Escape Clause', 'Once per session when under scrutiny by authorities, make a [B]Hard ([DI][DI][DI]) Knowledge (Core Worlds) check[b] to cite law or regulation that exempts or exonerates them. This does not need to be a true reading of the letter or spirit of this law or ordinance, and the character does not need to actually cite regulations that exist, they simply must have a convincing enough command of legal statutes to dissuade their immediate detainment.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GREAGOOD', 'For the Greater Good', 'Once per session after being successfully attacked, the character may make a [B]Hard ([DI][DI][DI]) Discipline check[b] to ignore the damage and the effect of this attack until the end of the encounter after which, the character suffers the damage, and the effects of any exceeded thresholds, status effects, or critical injuries, in that order.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESPKIND', 'Respond In Kind', 'May spend [TH][TH][TH] or [DE] from an incoming social check to add [SU][AD] to the next Charm, Negotiation, or Leadership check the character or an ally makes targeting that adversary.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNITPEOP', 'Uniter of People', 'Once per session, may choose a faction or group and make a [B]Hard ([DI][DI][DI]) Charm[b] or [B]Negotiation check[b]. On success, allied characters and the chosen faction within medium range add [AD] to skill checks this encounter. The character may spend [AD][AD][AD][AD] or [TR] to decrease the difficulty of all affected characters’ next check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACTILIST', 'Active Listener', 'When targeted by an opposed social check, may suffer 2 strain to oppose the check with Perception (Cunning) instead of Cool or Discipline.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CODEIMPR', 'Codebreaker (Improved)', 'Once per session, may choose a faction or group and make a [B]Hard ([DI][DI][DI]) Computers check[b] to gain insight on their plans or communications. On success, may add [FA] equal to ranks of Codebreaker to one check made by that group this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACTLISIMP', 'Active Listener (Improved)', 'When using Active Listener, may also suffer strain up to ranks of Perception to add that many [SE] to the check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEROEMBE', 'Heroic Embellishment', 'Once per encounter, may spend 1 Destiny point to add [AD] equal to ranks of Charm to an ally’s check. If that ally’s Duty triggered this session, add [TR] instead.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHIFNARR', 'Shift The Narrative', 'Once per session, choose an organization and make a [B]Hard ([DI][DI][DI]) Charm[b] or [B]Deception check[b]. On success, each member of that organization adds [SE] or [BO] to each check they make this session. The PC must have time and means to spread misinformation, and cannot use this action during a combat encounter.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARTYRDO', 'Martyrdom', 'Once per encounter after being successfully hit by an attack, may suffer 3 strain to add [DE] to the check. The [DE] result added this way do not include the [FA] result that are normally part of them, only the negative effects of the symbol.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHINARIMP', 'Shift The Narrative (Improved)', 'When taking the Shift The Narrative action, may spend [AD][AD][AD] or [TR] to increase or decrease the difficulty of the first check members of the targeted organization make each encounter this session.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHINARSUP', 'Shift The Narrative (Supreme)', 'The group affected by Shift The Narrative increases or decreases their wound threshold by 1, plus an additional 1 for each additional [SU][SU][SU] until the end of the session.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINDSTOR', 'Find The Story', 'Once per session, may make an [B]Average ([DI][DI]) Perception check[b] to identify a local compelling narrative. On success, add [SU] to all checks made to utilize that story this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WARIDEA', 'War of Ideas', 'When a foe makes a social check to persuade a third party, may suffer strain up to ranks of Knowledge (Warfare) to add that many [SE] to the check. If it fails, upgrade the ability of all social checks targeting that party or the foe once for the remainder of the session.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMEROUTF', 'Emergency Outfitting', 'Once per session, may make an [B]Average ([DI][DI]) Vigilance check[b] to reveal an undisclosed piece of personal gear, and may spend [AD][AD][AD] or [TR] to produce additional equipment equal to ranks of Vigilance.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FATAFLAW', 'Substandard Issue', 'Once per encounter, may make a [B]Hard ([DI][DI][DI]) Perception[b] or [B]Vigilance check[b] to determine that enemy equipment is substandard. Enemies equal to [SU][SU] add [TH][TH] to checks using this equipment in this encounter. The character may spend [AD][AD][AD][AD] or [TR] to have this affect all present enemies in the current scene.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORAGOOD', 'For A Good Cause', 'Once per session, may spend 1 Destiny Point to reduce purchase price of a single object or service by 5% times the character’s Contribution Rank. If being used in a campaign not using Duty, the Game Master may decide the seller''s disposition towards the character, and determine the price decrease that way.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MISAPPR', 'Misappropriate', 'Once per session, make a [B]Hard ([DI][DI][DI]) Computers[b] or [B]Skulduggery[b] check to reveal how a previously unknown theft or oversight has a meaningful impact on the scene. The player must justify how they or an intermediary had access to enemy supplies or logistics, and may spend [TR] to establish that the character or their allies has access to the missing resource instead, and may leverage it in the current scene.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WELLSUPP', 'Well-Supplied', 'Once per round when an ally attempts a skill check, may spend 25 credits times the difficulty of the check to add [SU] to that check. This talent may also be used on an allied Mass Combat check by spending 250 credits times the difficulty of the check, as determined by the size of the opposing force.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOOBTRAP', 'Booby Trap', 'Once per encounter, the character may take the Booby Trap action to use materials in their environment to assemble a trap within short range. Each time another character moves to engaged range of the trap, they must make an [B]opposed Vigilance vs. Skulduggery check[b] against the character who placed the trap. If the character who triggers the trap fails, they suffer wounds (these ignore soak) equal to the trapper''s Cunning characteristic, plus 1 additional wound per failure result. This damage profile may be changed to any explosive the character has available, adding 1 additional damage per [FA] on the check to notice the trap. This damage does not ignore soak. The trapper may spend [TH] generated to disorient the character for 1 round per [TH] spent, [TH][TH][TH] or [DE] to immobilize the character for 1 round, and [DE] to stagger the character for 1 round. 
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASKBLAS', 'Masked Blast', 'Before using explosives or otherwise making a large, noticeable, sound, the character may spend a Destiny Point to establish an even louder noise to mask it. This sound may be generated by the character, the environment, or some other source. Bystanders within earshot must make an [B]opposed Vigilance vs Stealth check[b] to notice the sound of the explosion.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTSABO', 'Master Saboteur', 'Personal-scale explosives the character uses or sets gain Sunder, and each [AD] spent to activate the Sunder quality damages the target item two steps instead of one.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONSTRUC', 'Constructor', 'When constructing bases, defenses, positions, or other similar combat engineering projects, add [BO] or remove [SE] per rank of Constructor.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONSTRIMP', 'Constructor (Improved)', 'While benefiting from cover from a position they have constructed, the character and allies increase their soak against ranged attacks by 1 per rank of Constructor.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COUNMOBI', 'Counter-Mobility', 'While defending a position, the character may make a [B]Hard ([DI][DI][DI]) Survival check[b]. On [SU], foes treat an approach to this position out to extreme range as difficult terrain. Spend [AD][AD][AD] to increase range to planetary close.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COUMOBIMP', 'Counter-Mobility (Improved)', 'Add [TH] to checks made by foes in the chosen approach. May spend [TH][TH][TH] from a foe’s check to immobilize them for rounds equal to characters ranks of Survival, or cause a minor collision.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONDIMP', 'Conditioned (Improved)', 'Once per session while falling, spend a Destiny point to reduce range bands fallen by ranks of Conditioned, to a minimum of Short. This affects the effective damage and strain suffered from the fall, not the fall distance itself.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIELRESE', 'Field Researcher', 'When the character makes a successful Knowledge check to gain information, reduce the difficulty of the next check they make to act on that knowledge by their ranks of Researcher, to a minimum of [B]Easy ([DI])[b].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HISTIMP', 'Historian (Improved)', 'Once per session when interacting with ancient or abandoned places or things, may spend 1 Destiny Point to cancel a [DE] or [TH] equal to ranks of Historian from a check the character or an ally makes.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWACTI', 'Knowledge In Action', 'When making a skill check involving technology, tools, or mechanisms, the character may spend a Destiny Point to substitute a Knowledge skill, per Game Master discretion, instead of the required skill.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STERSTUF', 'Sterner Stuff', 'Once per session, when the character would exceed their strain threshold, they may make a [B]Hard ([DI][DI][DI]) Discipline check[b] to reduce their strain to 1 below the strain threshold instead.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNEAANSW', 'Unearth the Answer', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Knowledge (Lore) check[b] to reveal that an item or place conceals a hidden secret that solves a problem in the current scene.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WATCSTEP', 'Watch Your Step', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Athletics check[b] to have all other characters within short range suffer 1 wounds plus 1 wound per each [SU]. Spend [AD] to exclude an ally from this effect per each [AD] spent. Spend [AD][AD][AD] or [TR] to Immobilize one affected enemy for one round. 
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HUNTSUP', 'Hunter (Supreme)', 'Before making a combat check against a non-sentient creature as a maneuver, suffer strain up to the target’s silhouette to reduce that attack''s critical rating by the same amount, to a minimum of 1.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINTUNIMP', 'Fine Tuning (Improved)', 'Once per encounter while engaged with or repairing a starship or vehicle, make a [B]Hard ([DI][DI][DI]) Mechanics check[b] to increase the system strain threshold of an the vessel by a number equal to the character''s ranks in Fine Tuning for the rest of the encounter. Spend [AD][AD][AD] or [TR] to have that vessel recover System Strain equal to ranks in Fine Tuning.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('QUICPICK', 'Quick Pickup', 'Once per encounter while piloting a starship or vehicle, make a [B]Hard ([DI][DI][DI]) Piloting check[b] to have any number of allies within medium range of the craft board it as an out-of-turn incidental.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DESPSCRA', 'Desperate Scramble', 'Once per session, make a [B] Hard ([DI][DI][DI]) Coordination check[b] to escape confinement through a previously unknown method. On success, the character is able to escape and may spend [AD][AD][AD] or [TR] to allow allies to follow. The nature of the escape method is Game Master discretion, but may be highly improbable.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEARJUMP', 'Fearless Jump', 'Once per session, may reroll a Astrogation check to make a hyperspace jump, and add [TR] [DE] to the result. [DE] added this way cannot be canceled by effects of talents, abilities, or equipment.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ODDJOB', 'Odd-Job', 'Once per session, after successfully negotiating to purchase goods or services, the character may offer to perform a task or favor in lieu of payment. If this task is not performed before the end of the session, they take Obligation equal to the original difficulty of the check to purchase, or based on credit cost, or other narrative factors, per Game Master discretion.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTNONE', 'Master of None', 'Once per round, add [SU] to a skill check the character makes using a skill that the they have less than 2 ranks in.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOLSTIMP', 'Bolster (Improved)', 'The benefits of the Bolster maneuver apply to all allies within short range as long as they remain within short range of the character.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KEEEYEIMP', 'Keen Eyed (Improved)', 'Once per session, make a [B] Formidable ([DI][DI][DI][DI][DI]) Perception[b] or [B]Vigilance check[b] to add [SU] to next checks they and allies make to act on the observation. Decrease difficulty of check once per rank of Keen Eyed.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATUREME', 'Natural Remedy', 'The character may use Survival instead of Medicine to heal wounds and critical injuries by increasing the difficulty of the check once.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONLOOK', 'On The Lookout', 'When making a check to determine initiative, spend a Destiny point to add [SU] to both their check and to a number of allies'' equal to ranks in Cunning.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('READWIND', 'Read The Wind', 'Once per encounter, make a [B]Hard ([DI][DI][DI]) Perception check[b]. On success, a moderate ([SE][SE]) environmental effect appears. Spend [TR] for a severe ([SE][SE][SE]) environmental effect. This hazard could be weather, man-made actions, or natural disasters.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REAWINIMP', 'Read the Wind (Improved)', 'May suffer 2 strain to perform the Read The Wind action as a maneuver.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('REAWINSUP', 'Read the Wind (Supreme)', 'Once per round, the character may suffer a number of strain up to their ranks in Perception to remove that many [SE] imposed due to environmental conditions from an enemy’s check, adding an equal number of [FA] or [TH] to that check. If four or more [SE] are removed this way, add a single [DE] to the check instead of [FA] or [TH].', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ITSABARG', 'It''s a Bargain', 'When buying goods, may have the item become damaged 1 step to reduce the price by 20%. Whether an item can be used while damaged is at Game Master discretion.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ITSASTEA', 'It''s A Steal', 'When selling damaged or misrepresented goods, may make an opposed [B]Deception vs. Vigilance[b] check, and treat their value as if they were undamaged and genuine. Add [SE] for each step of damage the item has, and upgrade the difficulty of the check if the item is not genuine.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARKCONN', 'Market Connections', 'May make a [B]Knowledge (Core Worlds) or Knowledge (Outer Rim) check[b] to locate a local seller willing to sell a particular legal good, and add [SU] to checks to purchase that item from that seller. The skill required is based on locale, and the difficulty of the check is equal to half the item’s rarity, rounded down.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARCONIMP', 'Market Connections (Improved)', 'The character may use Market Connections to locate a seller of an illegal good by substituting Knowledge (Society) instead of the required skill and upgrading the difficulty of the check once.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MARCONSUP', 'Market Connections (Supreme)', 'Spend [AD][AD][AD] or [TR] from Market Connections action to have the seller include a related item with a value and rarity no greater than half that of the original item, rounded down, at no additional cost. The item include is at Game Master discretion.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WHE&DEAIMP', 'Wheel & Deal (Improved)', 'When selling goods illegally, may upgrade the difficulty of the check once to gain 10% more credits per rank of Wheel and Deal. This includes locally restricted goods, stolen, and otherwise illegal goods.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOMEREAL', 'Something More Real', 'Spend 1 Destiny Point when negotiating the cost of goods or services to introduce physical goods to be bartered, counting the value of those goods at 125% of their current value, instead of or in addition to credits. Modify the check based on legality and the item''s level of damage.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERSBODY', 'Personal Body Guard', 'Once per encounter before an attack is made targeting an ally within short range, may move to their position and perform the Body Guard Maneuver as an out of turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERBODIMP', 'Personal Body Guard (Improved)', 'Once per session when performing the Body Guard Maneuver, may spend 1 Destiny point to have all attacks targeting the guarded character target the user instead until the user''s next  turn. Upgrade each attack targeting the character equal to the strain suffered performing the  Body Guard maneuver.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAWCOMIN', 'Saw it Coming', 'Once per encounter; make a [B]Hard ([DI][DI][DI]) Perception check[b] to add [TH][TH] to all attacks made against the character or allies within short range until their next turn. Spend [TR] to add [FA] to those attacks.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TIMTOGOSUP', 'Time To Go (Supreme)', 'Once per encounter when activating Time to Go, a number of allies equal to Cool may suffer 2 strain to also perform a maneuver as an out-of-turn move incidental to attempt to move into cover or out of the blast range of a weapon or explosion.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKIDOOR', 'Making A Door', 'Once per encounter, make a [B]Hard ([DI][DI][DI]) Skulduggery check[b] to treat an explosive as if it had the Breach 1 quality when breaching a specific structure or vehicle this encounter. Spend [AD][AD][AD] or [TR] to treat it as if it had Breach 2 instead.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STENERIMP', 'Steady Nerves (Improved)', 'Once per encounter when performing a check involving a precise and/or dangerous technical action, may suffer strain up to ranks of Steady Nerves to downgrade the difficulty of the check that many times.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEARIMP', 'Fearsome (Improved)', 'May Spend [AD][AD] from Coercion checks or [TH][TH] from foes’ Discipline check to have the target suffer strain equal to ranks of Fearsome.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SENDMESS', 'Sending a Message', 'Once per encounter, after incapacitating a foe or inflicting a critical injury, suffer 3 strain to add [TH] to all checks made this encounter by foes within Medium range equal to Willpower.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ORELSE', '…Or Else', 'Once per session, after the character or an ally within Short range makes a Coercion check that fails or results in [DE] spend a Destiny Point to add [TR] to the result.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LOCK&LOAD', 'Lock and Load', 'Once per encounter, the character may load or reload a weapon as an incidental, including those with the limited ammo quality. This talent reduces the amount of time to draw or stow a weapon that usually requires more than one maneuver to properly prepare or stow by 1 maneuver, or reduces its Prepare quality by 1.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUPFIRIMP', 'Suppressing Fire (Improved)', 'Foes who suffer strain from the effects of the character’s Suppressing Fire and foes within short range of the targeted character upgrade the difficulty of their next check once.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JUGGERNAUT', 'Juggernaut', 'When the character suffers a critical injury, spend a Destiny Point to reduce the Critical Injury result by 10 per rank of Resilience, to a minimum of 1.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KILORKILL', 'Kill Or Be Killed', 'Once per session when exceeding wound threshold, spend a Destiny Point to make a melee attack. If the target dies, wounds become equal to ranks of Resilience below threshold instead.', 'taActionOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAVARESP', 'Savage Response', 'When the character suffers a critical injury if they aren''t incapacitated, suffer 3 strain to inflict a hit with an equipped Melee or Brawl weapon on an engaged foe. This hit deals the weapon''s base damage plus any damage from applicable talents or abilities.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNYIELD', 'Unyielding', 'After being hit by a ranged attack, suffer 2 strain to perform a Move maneuver as an out of turn incidental toward the attacker.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FOCUFIRE', 'Focus Fire', 'Once per encounter, increase the difficulty of your next ranged combat check by 1. If successful, upgrade the ability of each combat check made against the target once until the end of the character’s next turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERTARIMP', 'Persistent Targeting (Improved)', 'After the character makes one or more successful combat checks against a target allies within short range of the character add [BO] to combat checks against that target for the remainder of the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CARGDROP', 'Cargo Drop', 'Once per encounter, may make a [B]Hard ([DI][DI][DI]) Skulduggery check[b] to dump the ship’s cargo. Foes within short range equal to [SU] must drop to speed 1 or suffer a major collision. The character may spend [AD][AD] or [TR] to trigger any additional effects, based on the nature of the cargo dropped, and Game Master determination.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MUSTSPEC', 'Mustafar Special', 'Once per round, may make an opposed Piloting vs Piloting check against starship or vehicle within close range. On Success, that craft suffers system strain equal to ranks in Cunning plus [SU]. Spend [AD][AD] to affect an additional craft within close range.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STELLDIST', 'Stellar Distraction', 'When a foe makes a check to detect, scan, or identify a starship the character is aboard, may spend 1 Destiny Point to upgrade the difficulty of that check a number of times equal to ranks in Astrogation.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WRETHIVE', 'Wretched Hive', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Astrogation[b] or [B]Knowledge (Underworld) check[b] to identify the path to the nearest Shadowport. Upgrade all checks to travel to and interact with the Shadowport this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENERSIPH', 'Energy Siphon', 'Once per encounter, make an [B]Opposed Athletics vs Athletics check[b] against an engaged foe to drain the energy from an equipped, powered item and recover strain equal to total encumbrance of drained item(s). Spend [AD][AD] or [TR] to drain an additional equipped item. Items drained cease functioning until either recharged or reloaded.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTCYBE', 'Master Cyberneticist', 'Once per round, suffer 2 strain to decrease the difficulty of the next check made to heal a cyborg or to create, install, repair, or activate a cybernetic once. This does not apply to checks that incidentally include the use of cybernetics.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STROFLES', 'Stronger Than Flesh', 'Once per encounter, may avoid suffering a [DI] or [DI][DI]  severity critical injury by having an installed cybernetic immediately malfunction. It provides no benefit until the character spends several hours making an [B]Average ([DI][DI]) Mechanics check[b] to repair it.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STRFLEIMP', 'Stronger Than Flesh (Improved)', 'Stronger Than Flesh may also be used to avoid crits of [DI][DI][DI] or [DI][DI][DI][DI] severity.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STRFLESUP', 'Stronger Than Flesh (Supreme)', 'Immediately after being successfully attacked but before suffering damage, spend 1 Destiny Point to increase the character''s Soak by half the number of their installed cybernetics, rounded up.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMERBYPA', 'Emergency Bypass', 'Once per encounter, when an engaged starship or vehicle suffers a critical hit, spend a Destiny Point and have the engaged starship or vehicle suffer system strain equal to the severity of that critical hit to choose a different critical hit of the same severity.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIGNSUPE', 'Signature Superiority', 'Once per encounter while aboard the Signature Vehicle, may make a [B]Hard ([DI][DI][DI]) Mechanics check[b].  On [SU], the character and a number of allies equal to the character’s Intellect add [SU] to all checks involving the signature Vehicle until the end of the character''s next turn.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TINKIMP', 'Tinkerer (Improved)', 'Once per session as an incidental, spend a Destiny Point. For each item benefiting from the character''s Tinkerer, add [AD] equal to the character''s ranks in Tinkerer to the next check using it.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PERMAI', 'Percussive Maintenance*', 'Once per encounter as a maneuver, before making a check to repair or damage an engaged machine, starship, vehicle, or droid, suffer 2 wounds to add [BO] equal to the character''s ranks of Melee or Brawl (whichever is higher) to the check.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIGVEHIMP', 'Signature Vehicle (Improved)', 'The character’s Signature Vehicle may have a silhouette or 5 or less. Increase the character’s Signature Vehicle''s top speed by 1, to a maximum of speed 6.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPECMODI', 'Special Modifications', 'Once per session, may make an [B]Average ([DI][DI]) Mechanics check[b] to temporarily convert an attachment currently installed on equipment or a vehicle into another valid attachment with equal or lesser hard points and rarity. They may make this permanent by spending 6 hours and spending credits equal to the new attachment''s cost minus the cost of the original attachment.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNLOPOTE', 'Unlocked Potential', 'Once per session, the character or an ally within short range may spend [AD][AD][AD] or [TR] from a check using a modded vehicle or piece of equipment to temporarily install a uninstalled Mod of an installed attachment of that item or vehicle until the end of the session (including a previously failed mod option). Additional [TR] may be spent from this or a subsequent check using the weapon or vehicle this session, paying normal modding costs, to unlock it permanently.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKEDANG', 'Make It Dangerous', 'Once per encounter, the character may perform the Make It Dangerous maneuver; the character makes a [B]Hard ([DI][DI][DI]) Knowledge (Education) check[b] to add choice of Burn 1, Sunder, or Vicious 1 to a weapon within engaged range until the end of the character''s next turn. If that weapon already has that quality, increase it by one rank. The Game Master may spend [TH][TH] or [DE] on this check or any check made using the weapon before this effect expires to damage it one step.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKDANIMP', 'Make It Dangerous (Improved)', 'Suffer 1 strain to decrease the difficulty of Make it Dangerous to [B]Average ([DI][DI])[b]. Spend [AD][AD][AD][AD] or [TR] so that all critical injuries inflicted by an attack using this weapon result in a Crippled effect, unless the roll would result in a more grievous injury. This effect lasts until Make It Dangerous expires.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DELARESP', 'Delayed Response', 'Once per session after being detected or discovered, may spend 1 Destiny Point to delay alarm, pursuit or reprisal until the end of the character''s next turn.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORCEXPL', 'Forceful Expulsion', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Computerscheck[b] to eject another character accessing a connected system. Spend [AD][AD] from this check or on a successful Eject User check to inflict strain equal to ranks of [B]Knowledge (Education)[b], and spend [TR] to render the chosen character''s slicer''s gear or access point unusable.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GHOSMACH', 'Ghost in the Machine', 'Suffer strain up to ranks in Stealth to add an equal number of [SE] or remove an equal number of [BO] from checks to trace, locate, or identify the character while they are slicing, including physical discovery.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LOGIBOMB', 'Logic Bomb', 'Once per session, make a [B]Hard ([DI][DI][DI]) Computers Check[b] and choose a connected system or device the character has access to, and a triggering event. On success, when the event occurs, the character may immediately enact a single command of their choice to that system or have it shut down, chosen at the time of triggering.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SHADSECR', 'Shadowfeed Secret', 'Once per session, may choose target location or faction, or person and make a [B]Knowledge (Underworld) check[b] with a difficulty based on the target. On [SU], may add [TR] to a Computers check to slice that target this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GLIDSTEP', 'Gliding Step', 'Add [BO] to melee attacks for each move maneuver performed this round.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKITCOU', 'Make It Count', 'Once per round, after an enemy cripples, destroys, or inflicts a critical hit on their ship or an allied ship within short range, may spend 1 Destiny Point to add [AD][AD] to the next check made by a number of allies equal to Presence.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BADMOTIMP', 'Bad Motivator (Improved)', 'Once per session when taking the Bad Motivator action, the character may choose a trigger or circumstance under which the device will fail, rather than it failing immediately. The device functions normally until that trigger occurs.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPDETSUP', 'Improvised Detonation (Supreme)', 'When taking the Improvised Detonation action, may add Burn +1, Concussive +1, Ensnare +1, Ion, Knockdown, Pierce +2, Stun +2, and/or Stun Damage qualities to the explosive, upgrading the difficulty of the check once for each quality chosen. Any number of qualities may be chosen, but each ranked option may only be chosen three times.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JAOATR', 'Jack of All Trades', 'When making a skill check using a skill with fewer ranks than their ranks of Jack Of All Trades, suffer a number of strain up to the difference to upgrade the ability of the check that many times.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSPIRINGLEADERSHIP', 'Inspiring Leadership', 'The character may take the Inspiring Leadership action by making an [B]Average ([DI][DI]) Leadership check[b].  If successful, a number of allies not exceeding his rating in presence within a short range add automatic [SU] to their next skill check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOSTIMPRESSIVE', 'Most Impressive', 'The character may spend [TR] from any skill check to allow a number of allies not excluding his rating in Presence within short range to add automatic [AD] to their next skill check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRIDEANDJOY', 'Pride and Joy', 'The character schooses one starship or vehicle with a silhouette of 4 or higher that they owns.  This vessel is the character''s "Pride and Joy" vessel.  They upgrade the ability of all social skill checks they makes while within short range of the vessel once.  If the vessel is ever lost or destroyed, the character may apply Pride and Joy to a new starship or vehicle that meets the requirements.  The process of modifying and acclimating to the new vessel may take some time at the GM''s discression.  No two characters can have the same vessel as their Pride and Joy.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRIDEANDJOYIMP', 'Pride and Joy (Improved)', 'While inside their Pride and Joy vessel, the character recovers one additional strain whenever they recover strain and may spend [AD] on checks made to recover strain to allow and ally also within the vessel to recover one strain.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRIDEANDJOYSUP', 'Pride and Joy (Supreme)', 'While inside their Pride and Joy vessel, once per session the character may reduce this vessel''s silhouette by two (to a minimum of 0) for the remainder of the round and the following round.  This lowered silhouette is used only for purposes of combat and movement, it does not physically reduce the size of the vessel.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRUSTHTECAPTAIN', 'Trust the Captain', 'May take the Trust the Captain action by making a [B]Hard ([DI][DI][DI]) Leadership check[b]. If successful, for the rest of the encounter allies within short range increase their ranks in Discipline by an amount equal to ranks in Trust the Captain.', 'taAction', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPDODGE', 'Improved Dodge', 'When the character performs the Dodge incidental, the character may make a Move maneuver as an out-of-turn incidental after the triggering attack has been resolved.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TOUGHENEDIMP', 'Toughened (Improved)', 'Once per session, the character may heal a number of wounds equal to their ranks in Toughened.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOCOAN', 'Boring Conversation Anyway', 'Once per round, may spend [AD][AD][AD] or [TR] on a social check to immediately make an attack against the target of that social check as an incidental.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DUBX', 'Double-Cross', 'Once per session, make a [B]Hard ([DI][DI][DI]) Deception check[b]. On success, the character (or player) reveals how their previously unknown scheming has a meaningful impact on the current scene or encounter. The nature of the revelation and its impact on the scene are ultimately subject to the GM''s discretion, but should inflict significant danger or disadvantage to an adversarial character. If the check fails and generates a despair result, however, the GM may decide that the character is actually the one being double-crossed.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAODL', 'Master of Dealing', 'Once per round, suffer 2 strain to reduce the difficulty of next check to find, buy, or sell stolen, contraband or illegal goods once.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRECON', 'Diagnostician', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Medicine check[b]. On success, the character (or player) details an observation they''ve made of a character within short range that reveals a medical condition they are suffering from. This condition may be purely narrative in nature and effect, but the Game Master may choose to impose negative effects on the diagnosed character.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DONOHA', 'Do No Harm*', 'Once per session, take the Do No Harm action; make a [B]Hard ([DI][DI][DI]) Cool check[b]. If successful, may not be targeted by combat checks until the end of the encounter, or until making a combat check. A Game Master may end this effect due to the character doing anything that would obviously injure, impede, or confound the enemy.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DRSORD', 'Doctor''s Orders*', 'When recovering under your supervision, characters heal an additional wound whenever they passively heal wounds, and add [SU] to any check to heal their critical injuries.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPSURG', 'Surgeon (Improved)*', 'When performing a Medicine check, may suffer strain up to ranks of Surgeon, then choose to either remove that many [SE] or add that many [BO].', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('VOIREA', 'Voice of Reason*', 'Once per encounter when making Leadership or Negotiation skill check, the character may use a Knowledge skill instead. Check uses Presence and player must explain how, in this particular instance, their Knowledge skill is persuading others or driving the conversation.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEALSELF', 'Heal Thyself*', 'When performing a check to heal themselves, may substitute Resilience instead of the required skill to avoid increasing the difficulty of the check.  This includes Mechanics checks to heal cyborgs or droids, but does not apply to Resilience checks to passively heal critical injuries. Talents that affect Medicine checks still apply to this roll.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CAPTAUDI', 'Captive Audience', 'Once per session, may make a [B]Hard ([DI][DI][DI]) Charm[b] or [B]Deception check[b] to captivate a group of people with a performance. On [SU], add [FA] to checks made by audience for the duration of the performance. May spend [TR] to add [FA][FA] instead.', 'taAction', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LIGHMOOD', 'Lighten the Mood', 'When recovering at the end of an encounter, may roll [B]Average ([DI][DI]) Charm[b] check. On Success, allies equal to Presence add [SU] to their recovery rolls. The character may spend [AD][AD] to have an affected ally add an additional [SU] to their check, and may spend [TR] to recover the same number of strain as one affected ally.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CANNIB', 'Cannibalize*', 'Once per encounter, the character may scrap an existing piece of similar gear to add [SU] to a check to create, improve or repair another piece of gear, mechanical object, starship, or vehicle.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FICAL', 'Field Calibration*', 'May make an [B]Average ([DI][DI]) Mechanics check[b] to add [SU] to the next check made by an ally using an engaged Vessel or piece of Equipment, and may spend [AD][AD] or [TR] to extend this effect to an additional check.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FICAIMP', 'Field Calibration (Improved)*', 'Once per round, may suffer 2 strain to perform Field Calibration as a maneuver.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JULINE', 'Just Like New*', 'Spend a Destiny Point to treat a non-destroyed piece of equipment within medium range as if it isn’t damaged until the end of the character''s next turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KIBA', 'Kitbash*', 'Once per session, the character may make a [B]Hard ([DI][DI][DI]) Mechanics check[b] and scrap a piece of gear to combine it with a vehicle or item with a larger silhouette, granting the latter item or vehicle a quality or feature from the scrapped item. The character may spend [AD][AD][AD][AD] or [TR] to reduce the [AD] cost to activate the chosen quality or feature by 1, to a minimum of 1. The GM may spend [TH][TH][TH] or [DE] on a future check using the item to have the kitbashed feature permanently fail, removing it from the larger device. An item may only benefit from one instance of Kitbash at a time. If Kitbash is ever applied to an item more than once, the previous iteration''s effects are overwritten.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOREIMP', 'Solid Repairs (Improved)', 'Once per encounter, the character may make a [B]Hard ([DI][DI][DI]) Mechanics check[b] to increase the armor of an engaged starship or vehicle by 1 until the end of the encounter. Spend [AD][AD][AD] or [TR] to have that vessel recover hull trauma equal to the character''s ranks of Solid Repairs.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DESFLA', 'Design Flaw (Improved)*', 'Take the Improved Design Flaw action; Make an [B]opposed Computers vs Discipline check[b] targeting a disabled or restrained droid, downgrading the difficulty of that check once per rank of Design Flaw the character possesses. On success, the character extracts useful information from the target’s databanks, and may spend [AD][AD] to alter information in the droid’s databanks, and/or [TR] to change a significant part of the droid’s base programming, including their loyalty and prime directive.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DIREC', 'Directive*', 'Once per round as a maneuver, suffer strain no more than ranks in Directive. Upgrade the ability of the next check made by an allied droid within short range a number of times equal to strain suffered.', 'taManeuver', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPDIREC', 'Improved Directive*', 'Once per encounter when performing the Directive maneuver, may affect an additional allied droid per rank of Directive, and the range of Directive increases to medium.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUPDIREC', 'Supreme Directive*', 'Once per session, choose a skill and make a [B]Hard ([DI][DI][DI]) Leadership check[b]. On success, a number of allied droids within medium range up to ranks of Directive may treat their ranks of that skill as equal the character’s ranks until end of character’s next turn. Spend [TR] to extend this effect 1 round.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINDIREC', 'Final Directive*', 'Once per session, when an allied droid would be incapacitated or destroyed, may spend 1 Destiny Point to allow that droid to make an immediate maneuver, followed by an action.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACCACC', 'Accomplished Accomplice*', 'Once per encounter, per Droid Companion, when an ally within short range of a Droid Companion would fail a check, the character may spend a Destiny Point to roll [BO] equal to that Droid Companion’s ranks in that skill, adding the results to the failed check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DROCOM', 'Droid Companion*', 'Choose a willing PC or NPC droid as a Droid Companion. Choose two skills. The Droid Companion adds automatic [AD] to checks using those skills. These skills may be changed with a [B]Hard ([DI][DI][DI]) Computers check[b] and six hours of reprogramming. If the droid is lost or destroyed, the character may apply Droid Companion to a new droid. The process of modifying and acclimating to the new droid is at the GM''s discretion. No two characters may have the same Droid Companion.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BINALLY', 'Binary Companions*', 'The Character may choose an additional willing PC or NPC droid as an additional Droid Companion per rank of Binary Companions. The character may choose different skills to add [AD] to for each Droid Companion.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MACMENIMP', 'Machine Mender (Improved)', 'When making a check to repair a droid, the character may spend [AD][AD] a number of times up to rank of Machine Mender to increase any combination the droid’s melee or ranged defense once per [AD][AD] spent until the end of the session, and may spend [TR] to increase its Soak by 1.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('THANMAK', 'Thank The Maker!', 'Once per session per Droid Companion, when a Droid Companion would be incapacitated or destroyed, spend a Destiny Point. It is not defeated until the end of the character’s next turn. If the droid is mechanically stabilized before the effect ends, it is not incapacitated or destroyed.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPREPPAT', 'Repair Patch Specialization (Improved)*', 'Once per droid per encounter, after applying a repair patch to a Droid, that droid adds [SU][AD] to the next check they make this encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMP', 'Compelling Counterpart*', 'Choose one social skill per Droid Companion. While engaged with Droid Companion, add [AD] to checks using the chosen skill.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DAZZFLOU', 'Dazzling Flourish', 'Spend [AD][AD][AD] or [TR] from a melee attack check to upgrade the ability of the next attack of each ally targeting that enemy.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CENTOATT', 'Center of Attention*', 'While making a social or performance check before a gathering or audience, may suffer 2 strain to gain [TR] on success or [DE] on failure. The [TR] or [DE] results added this way do not include the success or failure results that are usually part of them, only the beneficial or negative effects of the symbol.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ARMYOFONE', 'Army of One', 'Once per encounter after inflicting a critical injury or incapacitating a foe, the character may spend a Destiny Point to immediately make an attack against a different foe within range of an equipped weapon.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINISHFIGHT', 'Finish the Fight', 'After being successfully attacked, the character may suffer 2 strain to add damage equal to their ranks of Resilience to one hit of each attack they make before the end of their next turn.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FINISHFIGHTIMP', 'Finish the Fight (Improved)', 'After activating the Finish The Fight incidental, the character also adds 10 times their ranks of Resilience to the results of any Critical Injuries they inflict before the end of their next turn.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OUTFLANK', 'Outflank', 'Once per encounter, the character may perform a move maneuver as an incidental, then choose an enemy within range of an equipped weapon. Remove [SE][SE] from next attack the character makes against the chosen enemy this turn. This cannot allow the character to perform more than two maneuvers to move in a turn.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TACTICALDODGE', 'Tactical Dodge', 'After the character uses the Dodge incidental, if the incoming attack misses, the character upgrades the ability of the next attack the character makes against the attacker a number of times equal to the amount of strain suffered to activate Dodge this attack.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EVACTRAINING', 'Evac Training', 'The character ignores the encumbrance value of one character and their gear while carrying one or more other characters. A Game Master may determine some gear cannot be easily transported along with the carried character. The character adds [BO][BO] to Athletics and Coordination checks imposed due to carrying one or more characters.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POWERFULSTIMS', 'Powerful Stims', 'Once per encounter after administering a stim or stimpack, the character may spend 1 Destiny Point to add [SU] to each check made by the character who received the stim or stimpack until the end of the encounter.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNIVERSALRELIEF', 'Universal Relief', 'Once per session, choose a species and make a [B]Hard ([DI][DI][DI]) Knowledge (Xenology) check[b]. On success, the character adds [AD][AD] to the first check they make or assist with to interact with or heal each member of that species this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEADEYE', 'Dead-Eye', 'The character may benefit from a third aim maneuver on Ranged (Heavy) and Ranged (Light) attacks. It adds an additional [BO] if aiming normally, or removes an additional [SE] if aiming at a specific subset of the target.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DIALEDIN', 'Dialed In', 'Perform the Dialed In maneuver; make an [B]Average ([DI][DI]) Perception check[b] to treat all Ranged (Heavy) and Ranged (Light) attacks as if their maximum range was one ranged band further until the character moves more than short range from the spot they dialed in from or the encounter ends.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DIALEDINIMP', 'Dialed In (Improved)', 'Once per encounter, the character may spend [AD][AD] or [TR] from Dialed In to decrease the difficulty of all Ranged (Heavy) or Ranged (Light) attacks they make at Long or Extreme Range.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONESHOTONEKILL', 'One Shot, One Kill', 'Ranged (Heavy) and Ranged (Light) attacks the character makes gain +2 Pierce for each aim maneuver they are benefiting from.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERWATCHRE', 'Overwatch', 'Once per encounter, before a foe moves or acts, may make an [B]opposed Cool vs Vigilance check[b] against that foe, adding any relevant [BO] due to aiming. On success, they suffer a hit from an equipped ranged weapon with the appropriate range to attack the target plus 1 Damage per [SU]. The character may spend [AD] or [TR] results to inflict Critical Injuries and activate weapon qualities.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TIGHTGROUP', 'Tight Grouping', 'After making a Ranged (Heavy) or Ranged (Light) attack while aiming, if there is a foe within short range of the original target, or the original target isn''t defeated, the character may suffer strain up to the number of aims the attack was benefiting from to aim that many times as an incidental.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('AMBUSHER', 'Ambusher', 'Once per round when benefiting from cover or concealment, may make the Ambusher maneuver. Add damage equal to Stealth skill to one hit of the next successful non-starship/vehicle combat check made against a target within Medium range before the end of their turn.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXPLOITWEAKNESS', 'Exploit Weakness', 'Add [BO][BO] to attacks made against Disoriented, Immobilized, involuntarily prone, poisoned, Staggered, or incapacitated targets. Per GM discretion, other status effects may apply such as fires, acids, or particularly debilitating critical injuries.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GUERILLAWARFARE', 'Guerrila Warfare', 'Once per session, spend a Destiny Point. Until the end of the next round, the characters and their allies within Medium range may disengage from an enemy or enter cover once per turn as an incidental.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LAYOFTHELAND', 'Lay of the Land', 'Once per session, the character may make a [B]Hard ([DI][DI][DI]) Knowledge (Outer Rim) check[b] to establish an environmental factor that they are prepared for but an enemy faction is not. For all relevant checks this encounter, the character and their allies add [AD] and the chosen faction add [TH]. Spend [AD][AD][AD] or [TR] to increase the Defense rating granted by relevant cover by 1 (to a maximum of 3), and [TR] to have the enemy faction treat all relevant environments as difficult terrain.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ROADLESSTRAVELED', 'Road Less Traveled', 'Once per session, the character may make a [B]Hard ([DI][DI][DI]) Perception[b] or [B]Survival check[b] to establish a temporary shortcut between their present location and a location within Extreme range. As long as they stay on the shortcut, maneuvers the character and allies make to move directly towards the end location may move twice the distance this encounter. Spend [AD][AD][AD] or [TR] to add [SU] to all Stealth checks made by those on the path.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DANGERCLOSE', 'Danger Close', 'When the character engages a foe during combat, that foe adds [FA] to their next check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DANGERCLOSEIMP', 'Danger Close (Improved)', 'When the character engages one or more foes during combat, the character adds [SU] to their next check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEROICCHARGE', 'Heroic Charge', 'Once per round, the character may perform the Heroic Charge maneuver and suffer 2 strain to move to engage a character within Medium range that the character could otherwise reach.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HEROICCHARGEIMP', 'Heroic Charge (Improved)', 'After making the Heroic Charge maneuver, upgrade the difficulty of all ranged attacks targeting the character once until their next turn.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FEARLESSDIVERSION', 'Fearless Diversion', 'Once per session, the character may make a [B]Hard  ([DI][DI][DI]) Cool check[b] to draw the fire of enemies. A number of foes within medium range equal to [SU] must suffer 3 strain to attack an ally until the end of the next round. Each [AD][AD][AD] or [TR] may be spent to add [FA] to each attack targeting the character, and [TR] can be spent to determine an affected enemy cannot target anyone but the character.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BULWARK', 'Bulwark', 'If the character has attacked this round, allies within short range increase their Ranged defense by 1.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COLLATERALDAMAGE', 'Collateral Damage', 'Once per encounter after they miss an attack with an explosive or ordinance weapon, the character may spend a Destiny Point to reroll the attack against a different target within range. If the attack has the Guided quality and generated at least two uncancelled [AD] or a [TR], they may activate this incidental without spending a Destiny Point.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISRUPTIVE', 'Disruptive', 'Suffer a number of strain to downgrade the difficulty of a Computers check, or upgrade the difficulty when opposing a Computers check, by an equal number. Strain suffered this way cannot exceed ranks in Disruptive.', 'taIncidentalOOT', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISRUPTIVEIMP', 'Disruptive (Improved)', 'Spend [AD][AD] from a Computers check or [TH][TH] when opposing a foe''s computers check to add [FA] equal to the character''s ranks of Disruptive to a foe''s next Computers check in that system.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HUNTIMP', 'Hunter (Improved)', 'After the character inflicts a critical injury on or incapacitates a foe with an attack, or otherwise causes a critical injury or incapacitation of a foe, the character may perform a maneuver as an incidental. This does not allow the character to perform more than 2 maneuvers per turn, but may allow them to make maneuvers out-of-turn.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOLSPRES', 'Bolstering Presence*', 'Once per session, when an ally within Medium range would exceed their strain threshold, may spend 1 Destiny Point to have them recover strain equal to the character’s [B]Presence[b].', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('USERTALENT2', 'Reverse Engineering (Improved)*', 'May scrap the original item instead of paying credits when taking the Reverse Engineering action. May also spend [TR] to grant the item the [B]Superior[b] quality at the cost of one Hard Point or 0 Hard Points if the item doesn''t have Hard Points. If this item is not a weapon or armor, it gains a narrative benefit chosen by the Game Master and the Player.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUSTOMCODE', 'Custom Code', 'When your character selects this talent they choose one icebreaker or piece of ice that they own. If they choose an icebreaker, whenever they use that icebreaker to override ice, they add [AD] to the results. If they choose a piece of ice, whenever someone else attempts to override it, they add [TH] to the results.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CUSTOMRIG', 'Custom Rig', 'When your character selects this talent they choose one computer (such as a rig, PAD, or spinal modem) that they own. The amount of ice or icebreakers (your character''s choice) that they can have on that computer is increased by 1 per rank of Custom Rig. (This may be a mix of ice and icebreakers, as long as the combined total increase does not exceed your character''s ranks in Custom Rig). If your character loses their affected computer, they may choose a new computer to be affected by this talent.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NEXUSSEARCH', 'Nexus Search', 'When your character has access to the Nexus, they can use this talent to upgrade the ability of the next Knowledge check they make that turn twice, and the difficulty of the check once. [DE] means that they learn some seemingly relevant and believable information that turns out to be completely (and possibly maliciously) false.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CODESLINGER', 'Codeslinger', 'When your character performs the activate program maneuver in a hacking encounter, they can choose not to deactivate one other active icebreaker. They may have two icebreakers active at once.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NETHUNTER', 'Nexus Hunter', 'When your character successfully traces another character during a Network encounter, your character gains one additional trace.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NEXUSWARRIOR', 'Nexus Warrior', 'While accessing a system using a brain-machine interface (BMI), your character may use this talent to make an opposed Computers (Hacking) versus Computers (Sysops) check targeting one other character on the system that they are aware of. The target suffers 1 strain per [SU], and if they are using a BMI, they also suffer 1 wound per [SU].', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GHOSTMACHINE', 'Command Override', 'As long as they have some sort of access point to the Nexus, your character may use this talent to make a [B]Hard ([DI][DI][DI]) Computers (Hacking)[b] check . If they succeed, they may select one drone, vehicle, or piece of equipment involved in the current encounter and dictate its actions until the start of your character''s next turn.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WEBKNOWLEDGE', 'Web of Knowledge', 'Once per session your character may make an [B]Average ([DI][DI]) Knowledge (The Nexus) check[b] during a Nexus encounter. If you succeed, your character knows the names, strengths, and other qualities of all ice (active or deactivated) on one system that you currently have access to, as well as all other characters (sysops and runners) that currently are accessing that system.
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BURNTHROUGH', 'Burn Through', 'After making a successful break ice action, your character may suffer 3 strain to use this talent. If they do, they may perform a second override ice action on the same system as an incidental.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HITTHEDECK', 'Hit The Deck', 'After determining the character would be hit by an explosive, but before damage is applied, spend a Destiny point to perform a move maneuver as an incidental to move into cover or out of the blast radius of a weapon or explosion.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HITTHEDECKIMP', 'Hit The Deck (Improved)', 'When activating Hit The Deck, allies within short range of the character equal to Cool or Vigilance may also perform a Move maneuver as an incidental to move into cover out of a blast radius of a weapon or explosion.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXPLOSIVESURPRISE', 'Explosive Surprise', 'Once per session, make a [B]Hard ([DI][DI][DI]) Skulduggery check[b] to establish how a previously existing device or explosive the character possesses has been covertly placed somewhere within long range of them. Spend [AD][AD][AD][AD] or [TR] to allow the character to make an [B]Easy ([DI]) Mechanics check[b] as an incidental to activate or detonate the device while they are within extreme range of it. How the device was hidden is at the Game Master''s discretion.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OVERKILL', 'Overkill', 'Once per attack when the character causes a foe to exceed their wound threshold, the character may suffer 2 strain to assign a hit dealing damage equal to the incapacitating hit''s damage minus the original target''s soak to another foe within short range of the first. If this is a melee attack, the second target must be engaged rather than short range.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WHEREITHURTS', 'Where It Hurts', 'Once per encounter as a maneuver, the character may suffer strain up to their ranks in Perception and choose a foe within long range. The character''s attacks targeting the foe increase their Pierce rating equal to the number of strain suffered this way until the end of the encounter.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOLSTER', 'Bolster', 'As a maneuver, the character may remove [SE] per rank of Bolster imposed by a single environmental circumstance from all actions they make this encounter. This may be used multiple times to remove setbacks imposed by additional environmental circumstances.', 'taManeuver', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KILLERINSTINCT', 'Killer Instinct', 'Unarmed and improvised weapons attacks the character makes gain a Pierce equal to their ranks in Survival.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KILLCONFIRMED', 'Kill Confirmed', 'Once per session, upgrade the difficulty of the next ranged attack the character makes once to have one hit of that attack ignore the target''s soak. The Game Master may spend [TH][TH] or [DE] to have the weapon run out of ammo or otherwise malfunction.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FOLLOWMYLEAD', 'Follow My Lead', 'Once per round, spend [AD][AD] or [TR] from a check to allow an ally within short range count as having the same number of ranks of that skill as the character for the next check they make using that skill.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOTIMEBLEED', 'No Time To Bleed', 'Once per session, as a maneuver, spend a Destiny Point to recover strain and/or wounds in any combination up to ranks in Discipline.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MAKFIN', 'Makashi Finish', 'Take the Makashi Finish action; Perform a [B]Lightsaber (Presence) combat check[b] against engaged target, adding [FO] no greater than Force rating. Spend [FP] to add +10 to any resulting Critical Injury rolls.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SECRETJEDI', 'Secrets of the Jedi', 'Lightsaber becomes a career skill. He may also decrease to difficulty of checks made to construct or repair melee weapons a number of times equal to half his ranks in Knowledge (Lore) (rounded up), to a minimum of [B]Easy ([DI])[b].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FLYCASUAL', 'Fly Casual', 'Once per encounter while piloting, spend a Destiny Point to add [SE] equal to Cunning to a check made to identify, scan, or investigate the craft or its contents.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DYNAMICPER', 'Dynamic Personality', 'Once per encounter after making a successful social check, suffer strain up to the character''s Presence to increase or decrease an affected character''s defense by that number until the end of the next round. This cannot increase a character''s defenses above 4.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FRLOW', 'Friends in Low Places', 'Add [AD] per rank of Friends In Low Places to check the character makes to find or interact with the criminal element.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SWIND', 'Swindler*', 'Add [BO] or remove [SE] per rank of Swindler from checks to lie, cheat, steal, or commit subterfuge. Applicable checks are per GM discretion.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OPP', 'Opportunist', 'The character adds a [BO] per rank of Opportunist to combat checks made against enemies who have attacked an ally this round, or are otherwise distracted, per GM discretion.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FREERUNNINGSUP', 'Freerunning (Supreme)', 'When falling, the character reduces the number of range bands they fall by one. If falling less than short range, they suffer no ill effects from falling.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GOGROUND', 'Go To Ground', 'Once per session, make a [B]Hard ([DI][DI][DI]) Streetwise check[b] to establish a nearby location the character and their allies can lie low. If a base or safehouse already exists, add [SU] to checks made by the character or allies to reach it this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PLAINSIGHT', 'In Plain Sight', 'Once per session, make a [B]Hard ([DI][DI][DI]) Streetwise check[b]. On success, add [SU] to all checks the character makes to avoid scrutiny or identification, and [FA] to all checks made to identify or scrutinize the character this encounter. Spend [AD][AD][AD] or [TR] to extend these benefits to allies while they remain within short range.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HANDOFF', 'Hand Off*', 'Once per round, as an out-of-turn incidental, suffer 2 strain to covertly pick up or hide an engaged item that is encumbrance 1 or smaller, or exchange up to two items that are encumbrance 1 or smaller with an ally within short range. If the character is being closely watched, an [B]opposed Perception vs. Skulduggery check[b] can be made to notice the exchange, adding [SE][SE] to the pool.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INCITEIMP', 'Incite Distraction (Improved)', 'While piloting in traffic, a successful Incite Distraction check reduces the handling of foes'' craft within medium range by 2 until the end of the character''s next turn. Spend [TR] to reduce the speed of those craft to 0.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PACKAGESEC', 'Package Secured', 'Once per session when a valuable carried item is at imminent risk of being lost, stolen or discovered, spend a Destiny Point to add [TR] or [DE] to any one check related to maintaining control of the object.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COVERTRACKS', 'Cover Your Tracks', 'After incapacitating one or more foes, spend a Destiny Point to conceal the evidence of the attack. An opposed Stealth check against the character must be made to discover the attack.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GETINGETOUT', 'Get In, Get Out', 'Once per session, make a [B]Hard ([DI][DI][DI]) Skulduggery[b] or [B]Stealth check[b] to establish a previously unknown entry point to a structure or vehicle that the character and allies equal to Cunning may immediately use to infiltrate, even if it were otherwise impassable. Spend [TR] to allow stealthy exit through that point without requiring further checks.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SILENTTAKE', 'Silent Takedown', 'Once per encounter before making an attack against a target within short range, perform this maneuver. If that attack incapacitates the target, the attack is silent. The GM determines if a weapon can be used silently.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SILENTIMP', 'Silent Takedown (Improved)', 'Add [AD][AD] to attacks benefiting from Silent Takedown.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUBTERFUGE', 'Subterfuge', 'Once per session, make an [B]opposed Deception check[b] against a foe within short range to draw them in or lower their guard. On success, add [TR] to the next combat check the character makes against the foe before the end of the character’s next turn. Outside of structured time, this attack may be made immediately.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BEDSIDEMANNER', 'Bedside Manners', 'Add [AD][AD] to social checks the character makes against targets they have medically treated this encounter, or [SU][TH][TH] against those they have tortured, physically or otherwise.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FLIPSCRIPT', 'Flip the Script', 'Once per session when a foe targets an ally within short range of the character with a social check, spend a Destiny Point to have that ally make the same check against the foe instead. This check benefits from skilled assistance from the character.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LOOSELIPS', 'Loose Lips...', 'Once per session, make an [B]opposed Charm vs Cool[b] or [B]Deception vs Discipline check[b] against a non-hostile NPC to glean actionable intelligence. On success, add [TR] to a check the character or an ally makes that uses this intel while acting against the target NPC''s organization.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POTENTTINC', 'Potent Tinctures', 'Foes upgrade the difficulty of checks made to resist the effects of poisons that were created or administered by the character once per rank of Potent Tinctures.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SINKSHIPS', '...Sink Ships', 'After the character successfully takes the …Loose Lips action, they may choose to add [DE] to a  check relevant to the intel made by the target NPC’s organization instead of adding [TR].', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEATHBEFOREDIC', 'Death Before Discovery', 'Once per session, spend a Destiny Point to add [TR] to a combat check the character makes against someone who has just or is about to uncover their identity or mission.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENOUGHTOGET', 'Enough to Get By', 'Once per encounter, suffer two strain to add [BO] equal to the character’s ranks of Knowledge (Education) to a single check they make.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FALSETRAIL', 'False Trail', 'Add [SE] per rank of False Trail to checks to investigate, scrutinize, or interrogate the character. Spend [TH][TH][TH] or [DE] to implicate or redirect suspicion to a specific third party known to the character. The GM may add equivalent [BO] to similar checks the character makes instead.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('OFMANYFACES', 'Of Many Faces', 'At the beginning of each session, choose one unranked skill in which the character possesses no ranks to gain two temporary ranks, or two unranked skills to gain one rank each. This effect lasts until at the end of the session.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SLEEPERACTIVATE', 'Sleeper Activate', 'Once per session when voluntarily abandoning a cover story, façade or persona, as an incidental, make a [B]Hard ([DI][DI][DI]) Cool[b] or [B]Discipline check[b]. On Success, add [SU] to all checks the character makes this encounter. Spend [TR] to reduce the difficulty of those checks once instead.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNWITTINGACCOMPLICE', 'Unwitting Accomplice', 'Once per session while undercover, make a [B]Hard ([DI][DI][DI]) Charm[b] or [B]Deception check[b] to have a character in the scene, or one that conveniently appears, vouch for the character’s cover story. That character provides assistance on social checks for the remainder of the scene, per GM discretion.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FALSETRAILIMP', 'False Trail (Improved)', 'The character may choose to upgrade the difficulty of affected checks a number of times equal to their ranks of False Trail instead of its normal effects. Spend [DE] to describe how the character laid the trap that implicated the foe making the check.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ACCORDINGDESIGN', 'According to My Design', 'Once per session after a check the character or an ally within medium range makes results in [DE], suffer 4 strain to add [TR] to that check. The player should establish how they planned for exactly this eventuality.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASSETACQUIRED', 'Asset Acquired', 'Once per session, spend [AD][AD][AD] from a Streetwise or Social check made to gather information to increase the members within an intelligence network or the scope of a contact network once until the end of session.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLENDINGIN', 'Blending In', 'Suffer 2 strain to make a Stealth check with Cunning instead of Agility.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COMPROMISEDRE', 'Compromised', 'Once per session, make a [B]Hard ([DI][DI][DI]) Coercion[b] or [B]Deception check[b]. On a success, a foe is convinced the character has compromising evidence, and will assist the character for the rest of the encounter, per GM discretion. Spend [AD][AD][AD] or [TR] to have the foe assist the character for the rest of the session, instead.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EYESANDEARS', 'Eyes and Ears Everywhere', 'When in a well-populated or urban location, the character may substitute Streetwise for checks to determine initiative. The Game Master determines which locations qualify.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NEEDTOKNOWRE', 'Need to Know', 'Once per encounter, when making a Leadership skill check, the character may use Deception instead of Leadership. The character''s Deception skill is combined with their Presence Characteristic to form the dice pool.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOLOOSEENDSRE', 'No Loose Ends', 'Once per session when making a check that utilizes an intelligence or contact network, spend a Destiny Point to remove [SE] equal to the character''s ranks of Willpower, or to have a failed check succeed as if a single [SU] had been the result. If they do, reduce the intelligence network by one member or the contact network''s scope by one.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PLANSWITHINPLANSRE', 'Plans Within Plans', 'Once per encounter, make a [B]Hard ([DI][DI][DI]) Knowledge (Warfare)[b] or [B]Streetwise check[b] to establish a previously unknown covert plan that is coming to fruition during this encounter. Add [SU] or [FA] to one plan-related made during this encounter, plus one check for each [SU][SU] past the first.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PLANSWITHINPLANSIMP', 'Plans Within Plans (Improved)', 'Spend [AD][AD][AD] or [TR] from Plans Within Plans to choose to add [SU] or [FA] to checks affected by Plans Within Plans after they are rolled, but after results are determined, rather than before.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPYMASTERRE', 'Spymaster', 'Once per round, suffer 2 strain to decrease the difficulty of a check made to create or utilize the character''s contact or intelligence network.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('VEILEDTHREATS', 'Veiled Threats', 'Make a [B]Hard ([DI][DI][DI]) Coercion or Deception check[b] to upgrade the difficulty of the next check made by foes equal to Cunning. Spend [TR] to upgrade one of those foe''s checks once for the rest of the encounter instead.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ASTUOBSE', 'Astute Observation', 'Once per encounter, may add [BO] equal to ranks in Astute Observation to an ally’s check.', 'taIncidentalOOT', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PATHSUNCHARTED', 'Paths Uncharted', 'Once per session, make a [B]Daunting ([DI][DI][DI][DI]) Astrogation check[b] to find an uncharted hyperspace route. On success, the route is either immediately ready for the character jump as an incidental, untraceable and unrepeatable by anyone but the character, or the shortest possible in both distance and time. Spend [AD][AD][AD] or [TR] to pick additional effects.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HOTSWAP', 'Hot Swap', 'After changing weapons, add [BO] per rank of Hot Swap to the next attack made with weapons not yet used in this encounter.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPOSINGLEADER', 'Imposing Leader', 'Suffer 2 strain to make a Leadership check with Willpower instead of Presence.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NEGATIVEREINFORCE', 'Negative Reinforcement', 'Make a [B]Hard ([DI][DI][DI]) Coercion or Leadership check[b]. On success, characters equal to Willpower suffer 1 strain and add [AD] to their next check if an ally, or [TH] if a foe.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WILLBREAKERIMP', 'Willbreaker (Improved)', 'Once per encounter, if Willbreaker would affect a foe already at 1 Willpower, spend a Destiny point to incapacitate them.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WILLBREAKER', 'Willbreaker', 'Spend [AD][AD][AD] or [TR] from melee attacks or Coercion checks to reduce a target’s Willpower by 1 until the end of the encounter (to a minimum of 1). Spend an additional [TR] to reduce it by two instead.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
