INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IRONWILLED', 'Iron-Willed', 'Once per session, suffer 2 strain to treat the character as if their Willpower was one higher until the end of the encounter.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('THEYCANTREFUSE', '...They Can''t Refuse', 'Once per session, before making a social check, suffer 3 strain to substitute Coercion instead of the required skill. On success, add [DE] to a target’s next check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NEGATIVEREIMP', 'Negative Reinforcement (Improved)', 'The difficulty of Negative Reinforcement is reduced to [B]Average ([DI][DI])[b]. Spend [TR] to double the number of [AD] and [TH] added.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CYBERCOLOSSUS', 'Cyber Colossus', 'Once per session as a maneuver, make a [B]Daunting ([DI][DI][DI][DI]) Resilience check[b] to ignore the effects of damaged or missing cybernetics until the end of the encounter. This includes the effects of critical injuries that affect one or more cybernetics.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CYBERJUNKY', 'Cyber Junky', 'Decrease the difficulty of checks to install cybernetics on the character once per rank of Cyberjunky. Cybernetics cost 50% less to build, purchase, or repair. This discount does not increase with multiple ranks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LIMITBREAKER', 'Limit Breaker', 'Once per round after performing the Move maneuver, the character may suffer 2 wounds to perform an additional Move maneuver. This may allow the character to make more than 2 maneuvers per turn.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LIMITBREAKERIMP', 'Limit Breaker (Improved)', 'Once per encounter after making a combat check, the character may spend a Destiny Point and suffer 4 wounds to make an additional attack using the same weapon(s).', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNNATURALREFLEXES', 'Unnatural Reflexes', 'Once per round when targeted by a combat check by an enemy within long range, spend a Destiny Point to upgrade the difficulty of the check a number of times equal to the character''s ranks in Vigilance.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GALMAP', 'Galaxy Mapper', 'Remove [SE] per rank of Galaxy Mapper from Astrogation checks. Astrogation checks take half of the normal time.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIGVEH', 'Signature Vehicle', 'Choose one starship or vehicle as Signature Vehicle. Upgrade all Mechanics checks made on that vehicle once.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STRSMART', 'Street Smarts', 'Remove [SE] per rank of Street Smarts from Streetwise or Knowledge (Underworld) checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('IMPCONC', 'Improvised Concoction', 'Once per session, as an action, make a [B]Hard ([DI][DI][DI]) Knowledge (Xenology) check[b], adding [FO] no greater than Force rating to create 1 dose of a poison or drug with rarity of Intellect + [SU] + [FP] spent or lower.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SECRETLORE', 'Secret Lore', 'Remove [SE] per rank or Secret Lore from all Knowledge (Lore) checks. Reduce the difficulty of all Knowledge (Lore) checks by 1.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BENEVOLENTPATR', 'Benevolent Patronage', 'Once per session, make a [B]Daunting ([DI][DI][DI][DI] Charm or Negotiation check[b] to invoke the aid of a powerful patron to resolve a social, legal, or logistical problem. The patron may have conditions of this assistance, per GM discretion. The character may gain +1 obligation to the patron, or upgrade the difficulty of all social checks made against this patron once until this condition is met.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EXUDECON', 'Exude Confidence', 'When an incoming social check generates [TH][TH] or [DE], suffer strain up to ranks of Cool to add [FA] or [SU] to the next check by that many characters within medium range.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FRIENDLOWIMP', 'Friends in Low Places (Improved)', 'Once per encounter, suffer strain up to ranks in Friends in Low Places to decrease the difficulty of a check to interact with the criminal element that many times, to a minimum of [B]Easy ([DI]).[b]', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POWERBROKER', 'Power Broker', 'Once per encounter, suffer 2 strain to add [SU] to a social check that invokes a patron or organization, or to interact with members of that organization.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POWERBROKEIMP', 'Power Broker (Improved)', 'Once per session when activating Power Broker, suffer 4 strain instead to add [TR] rather than [SU].', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SCAPEGOAT', 'Scapegoat', 'Once per session after making a social check, spend a Destiny Point to remove [DE], or [TH] equal to the character''s ranks of Deception from the results. If the character has implicated a present character, they add the removed symbols to their next check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TIMESPLITTER', 'Time-Splitter', 'Once per encounter, the character may perform the Time-Splitter maneuver to ignore a weapon''s Slow-Firing quality this turn and upgrade the difficulty of the next check using it equal to its ranks of Slow-Firing. This may also allow the character to use a weapon that has already been fired this round by upgrading the difficulty of that attack equal to the number of times it has been fired this round.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BADINFO', 'Bad Info', 'Once per session, the character may make an [B]opposed Knowledge check[b] against a character in the scene. On success, the player establishes the target has acted on untrue or faulty information that the character is aware of. Until the end of session, the player made add [DE] to a single check made by the target based on that bad information. The nature of the information is up to Game Master discretion.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DIRTYSECRETS', 'Dirty Secrets', 'Once per session, the character may make a [B]Hard ([DI][DI][DI]) Knowledge (Underworld) check[b] to reveal a character''s dirty secret(s). On success, add [FA] to all social checks they make for the rest of the encounter. The character may spend [AD][AD] to add [TH] to those checks for each [AD][AD] spent this way.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TRADEINSECRETS', 'Trade In Secrets', 'When purchasing goods or services, the character may offer information they possess to be traded in addition to glass, adding a number of [BO] to the check based on the nature and value of the information, per GM discretion. [AD][AD][AD][AD] or [TR] may be spent to establish information of equal value being given to the character at no cost.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SCRAPPY', 'Scrappy', 'Remove [SE] per rank of Scrappy from Skullduggery and Survival checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LOWBLOWRE', 'Low Blow', 'Attacks benefiting from aiming inflict an additional amount of strain equal to 1 plus ranks of Low Blow (bypassing Soak).', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANYTHINGKILLS', 'Anything Can Kill', 'Once per round as a maneuver, make an [B]Average ([DI][DI]) Survival check[b] to discover or fashion an improvised weapon with a choice of Disorient 3, Ensnare 2, or Vicious 2. Spend [AD][AD][AD] to choose an additional quality, and spend [TR] to reduce the critical rating by 1.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CREATIVEIMPROVED', 'Creative Killer (Improved)', 'The character does not add [TH] to combat checks due to using an improvised weapon. Increase the damage of improvised weapons by 2.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANYTHINGKILLSIMP', 'Anything Can Kill (Improved)', 'When making a combat check with an improvised weapon, destroy that weapon to add [PR] to the pool.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LOWBLOWIMP', 'Low Blow (Improved)', 'Once per encounter, spend a Destiny Point to remove any number of [BO] from a combat check to add that many [AD] to the check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
