INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLACKOUT', 'Blackout', 'Once per encounter, make a [B]Daunting ([DI][DI][DI][DI]) Computers check[b] to disrupt enemy communications. Add [SE] to all checks made by opposing forces for rounds equal to [SU]. Spend [AD][AD][AD] to add [FA] to the next check each foe makes.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLACKOUTIMP', 'Blackout (Improved)', 'Decrease the difficulty of Blackout to [B]Hard ([DI][DI][DI]).[b] Additionally, spend [TR] to keep an enemy leader from upgrading the next ability or difficulty of the next Mass Combat check made this encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COUNTERINT', 'Counter-Intelligence', 'Once per session, make a [B]Hard ([DI][DI][DI]) Knowledge Warfare check[b] to disseminate false military info. On success, may add [DE] to a relevant check made by the misled faction before the end of this session. The character must establish how the information gets to said enemy.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CRITICALVULN', 'Critical Vulnerability', 'Once per session, make a [B]Hard ([DI][DI][DI]) Computers check[b]. If successful, one computer-attached device or security system (subject to the GM''s approval) fails or has its functionality fundamentally altered, either due to the character''s involvement or because it was about to fail anyway.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISRUPTIVESUP', 'Disruptive (Supreme)', 'Once per encounter after a foe makes a check that includes a computer system the character owns or has accessed this encounter, spend a Destiny Point to have that foe reroll a number of positive dice equal to the character''s ranks of Disruptive, keeping the new results.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('JETPEXP', 'Jetpack Expertise', 'The character may spend [AD] from checks they make to remove 1 system strain from a jetpack they are equipped with. (They may choose this effect multiple times when spending [AD].)', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HITANDRUN', 'Hit and Run', 'While the character is using a jetpack, after they complete an attack targeting an opponent they are engaged with, the character may immediately disengage as an incidental.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEATHABOVE', 'Death from Above', 'Once per encounter while using a jetpack, the character may take the Death from Above action, inflicting 1 system strain on their jetpack and making a [B]Hard ([DI][DI][DI]) Piloting (Planetary) check[b]. If the check is successful, for each [SU], one adversary of silhouette 0 or 1 within short range is knocked prone. The character may spend [TR] from the check to stagger one affected adversary until the end of the adversary''s next turn.', 'taAction', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TOTHEDEATH', 'To the Death!', 'Once per session, the character may take the To the Death! maneuver, suffering strain no greater than their Willpower rating. For each strain suffered this way, add +10 to Critical Injury rolls the character inflicts and suffers until the end of the encounter.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MOMENTUM', 'Momentum', 'When making a melee attack, the character deals additional damage equal to the number of range bands they moved during the current round.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIDESTEPIMP', 'Side Step (Improved)', 'When the character performs a Side Step maneuver, until the start of their next turn, they may spend [TH][TH][TH] or [DE] from a combat check targeting them to inflict one hit on that attacker from a Ranged (Heavy) or Ranged (Light) weapon the character is currently wielding. The hit deals its base damage plus any damage from applicable talents or abilities. This talent may not be used if the original attack incapacitates the character.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ICHORBLADE', 'Ichor Blade', 'When the character purchases this talent, choose one Melee or Brawl weapon they possess that does not feature electronic or other high-tech parts. (For example, they could choose a sword or staff, but not a vibroknife or electrostaff.) The weapon gains the Cortosis and Pierce 2 item qualities and reduces its critical rating by one to a minimum of 1. In addition, any other character adds [SE] to checks they make to use this weapon. If the weapon is ever lost or destroyed, the character can apply Ichor Blade to a new weapon. If the weapon leaves the character''s possession for longer than a single scene or encounter, it loses all effects of this talent until the character reacquires it.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ICHORBLADEIMP', 'Ichor Blade (Improved)', 'The weapon affected by the character''s Ichor Blade talent also gains the Sunder and Defensive 1 item qualities, and increases its damage by 2.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ICHORTRANS', 'Ichor Transfusion', 'Once per encounter, the character may perform the Ichor Transfusion maneuver. The character may heal any number of their current wounds by suffering that number of strain +1. The character may instead heal any number of their current strain by suffering that number of wounds +1.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('COVEN', 'Coven', 'The character may perform the Coven maneuver. On their next Force power check, they may reroll one [FO] for each ally within short range who also possesses the Coven talent.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WITCHCRAFT', 'Witchcraft', 'The character gains a Force rating of 1. If the character already has a Force rating of 1 or higher, there is no effect.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SURVINST', 'Survivor''s Instincts', 'Once per session when the character suffers a Critical injury spend 1 Destiny Point. Then the attacker must roll two results for the Critical Injury and the player choose which will apply to their character.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUMMONITEM', 'Summon Item', 'When the character purchases this talent, choose one item they own of encumbrance 4 or less. As a maneuver, the character can summon this item to their hand or dismiss it from their hand back to the depths of Dathomir, regardless of the character''s location. Once per session, the character can spend one hour to ceremonially prepare a different item to be summoned. The character can have only one item prepared in this way at a time.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAVVY', 'Savvy', 'The character adds [BO] to Charm and Negotiation checks they make per rank of Savvy.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLATHER', 'Blather', 'The character may take the Blather action, making a [B]Hard ([DI][DI][DI]) Charm[b] or [B]Deception check[b]. If the check is successful, one adversary per [SU] within medium range is disoriented for a number of rounds equal to the character''s presence rating. The character may spend [TR] from the check to stagger one affected target for one round.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DIPIMMUN', 'Diplomatic Immunity', 'Once per encounter, the character may perform the Diplomatic Immunity incidental. The character spends one Destiny Point and adversaries cannot choose the character as the target of a combat check until after the end of the character''s next turn. This effect ends if the character makes a combat check.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESALLOC', 'Resource Allocation', 'At the beginning of a mass combat, the character may make a [B]Hard ([DI][DI][DI]) Charm[b] or [B]Negotiation check[b] to increase their force''s strength by one step for the duration of the encounter. The character may spend [TR] from the check to upgrade the ability of their force''s first Mass Combat check once.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DELAYEDDOSE', 'Delayed Dose', 'After a foe fails a check to resist the effects of poisons, the character may choose to delay the effects. Before the end of session as an incidental, the character may spend a Destiny Point to have the foe immediately suffer the effects of the poison, determined by the earlier check to resist. If the session ends before the character does so, the GM decides the ramifications of the poisoning.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HIDDENFANGS', 'Hidden Fangs', 'When making a combat check with a poisoned weapon, suffer 2 strain to substitute Skulduggery instead. The character''s Skulduggery skill is combined with the required characteristic to form the dice pool.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NEUTRALIZER', 'Neutralizer', 'Once per encounter, suffer 3 strain to add [TR] to a check they make targeting a poisoned character, including curing a poisoned ally or attacking a foe that the character themselves poisoned.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PICKYOURPOI', 'Pick Your Poison', 'Once per encounter, make a Knowledge (Xenology) or Survival check to create, extract, or source a single dose of poison from a natural environment. The difficulty is equal to a check made to buy it, based on rarity. Spend [TR] to find a concentrated version, which adds [FA] to any checks made to resist it this session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POTENTTINCIMP', 'Potent Tinctures (Improved)', 'Spend [DE] from a check made to resist a poison the character created or administered to have the foe suffer a Critical Injury, adding +10 times the Character''s Cunning to the result. Additional [DE] may be spent to add an additional +10 times the character''s Cunning.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POTENTTINCSUP', 'Potent Tinctures (Supreme)', 'Once per session, spend a Destiny Point to force a foe to re-roll a check to resist a poison the character created or administered.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BADINFLU', 'Bad Influence', 'Spend [TH][TH][TH] or [DE] from a foe''s social check to upgrade the ability of social checks the character makes against that character until the end of the encounter. This may only be used once per character per encounter.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BADTRIP', 'Bad Trip', 'Once per session, spend a Destiny Point to add [DE] to a check made by a character who is under the influence of or has been exposed to drugs or similar substance.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FIRSTONEFREE', 'First One is Free', 'Once per session, make a [B]Hard ([DI][DI][DI]) Streetwise check[b] to identify a nearby desperate spice-user. On success, they will perform a favor in exchange for one or more doses of an illicit substance, with the amount depending on the danger or legal status of the favor, at GM''s discretion.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPICELIFE', 'Spice of Life', 'Once per round per character, the character or an ally under the influence of drugs created or supplied by the character may suffer 2 strain as an incidental to add [SU] to their next check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SPICELIFEIMP', 'Spice of Life (Improved)', 'Once per session, a character under the influence of the character''s drugs may suffer 2 strain and upgrade the difficulty of the check once to add [TR] instead.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SIDEDIPL', 'Sidearm Diplomacy', 'Once per encounter, may upgrade the difficulty of a social check the character makes once to add [SU] equal to ranks in Sidearm Diplomacy to the results.', 'taIncidental', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BREAKTHROUGH', 'Breakthrough', 'Once per session when making a check to solve a mystery, the character may spend a Destiny Point to add [BO] equal to the number of clues the character has discovered, to a maximum of [BO][BO][BO][BO][BO]. What constitutes a clue is up to GM discretion.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CHASELEAD', 'Chase the Lead', 'Once per session when investigating a crime, case or mystery, the character may introduce a new source, witness, or clue that assists with the investigation as if a Destiny Point had been spent. The provenance of this new information is per GM discretion, but should meaningfully assist the character''s aims.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CROSSEXAMINE', 'Cross-Examine', 'When targeted by a social check, may spend [TH][TH][TH][TH] or [DE] to add [FA] to social checks the character makes until the end of the encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEDREASONING', 'Deductive Reasoning', 'Once per encounter, make an [B]Average ([DI][DI]) Knowledge (Education)[b] or [B]Perception check[b] to connect a target to a location or event. The character may ask the GM a general question about the target''s background for each [SU], and about the target''s emotional state for each [AD]. [TR] may be spent to ask specific questions relating to an event or investigation.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INQUIRE', 'Inquiring', 'When investigating a case add [BO] or remove [SE] from the check per rank of Inquiring.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INQIMP', 'Inquiring (Improved)', 'Before rolling a social check while investigating a crime, the character may remove [BO] up to their ranks in Inquiring from the pool, and add an equal number of [SU] or [AD] results (in any combination) to the results.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLOOLUST', 'Bloodlust', 'After incapacitating or inflicting a Critical Injury on a foe, add [BO] per rank of Bloodlust to the next check the character makes this encounter.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HISTORIAN', 'Historian', 'When recalling information about or interacting with ancient or abandoned places or things, add [BO] or remove [SE] per rank of Historian.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BARGHUNT', 'Bargain Hunter', 'When the character makes a check to purchase or sell goods or services, they add [BO] or remove [SE] equal to their ranks of Bargain Hunter.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MACMANIMP', 'More Machine Than Man (Improved)', 'Before making a check, suffer strain up to half of the the number of character''s installed cybernetics, rounded up, and add that many [BO] to the check. The player must specify how one or more of their cybernetics are aiding them for this check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DROIDCOMMIMP', 'Droid Commander (Improved)', 'As an action, may make an [B]Average ([DI][DI]) Leadership check[b]; 6 allies may immediately suffer 1 strain to perform a free maneuver; may spend [TR] to allow one ally to perform an action; once per encounter, perform as a maneuver but affect only droid allies.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INGRAINLOY', 'Ingrained Loyalty', 'When the character makes a Leadership check targeting one or more clones and no other characters, they may change the result of one [CH] to any non-blank face.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NOTRY', 'There Is No Try', 'Once per session before any ally rolls the dice for a check, the character may spend a Destiny Point to allow the ally to automatically succeed at the check with one success and no other results.', 'taIncidentalOOT', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORMTACTIMP', 'Formation Tactics (Improved)', 'The difficulty of taking the Formation Tactics action is reduced to [B]Average ([DI][DI][b] instead of [B]Hard ([DI][DI][DI])[b]. The character may also spend a [TR] or [AD][AD][AD][AD][AD][AD] results to have the effect last until end of encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CENTBEINGSUP', 'Center of Being (Supreme)', 'When the character performs the Center of Being maneuver, until the beginning of their next turn, ranged weapons also treat their critical rating as one higher per rank of Center of Being when attacking the character.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CLANKKILLIMP', 'Clanker Killer (Improved)', 'When making a Brawl or Melee combat check targeting a droid, the character treats their attack''s critical rating as being 1 lower per rank of Clanker Killer (to a minimum of 1).', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ATANYCOST', 'At Any Cost', 'The character may suffer a Critical Injury to force a Mass Combat check to be rerolled. At the GM''s discretion, the character may be required to sacrifice an item, vehicle, or individual of personal significance instead.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BOUNDTO', 'Bound Together', 'The character may perform the Bound Together maneuver. Until the start of the character''s next turn, when the character or an ally within short range suffers strain involuntarily, they reduce the amount suffered by the current number of light side Destiny Points in the destiny pool.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GETDROP', 'Get the Drop', 'Once per session, the character and any number of allies in the current encounter may add [SU] equal to the character''s ranks in Stealth to a check to determine Initiative order. The player must explain how their character''s stealthy approach helps the PCs to get the drop on their opponents.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('POWALLY', 'Powerful Ally', 'The character may spend a Destiny Point to use the basic version of a Force power they have not purchased or to apply the effects of a single unpurchased control upgrade to a power they have purchased.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FALLBACK', 'Fall Back!', 'While engaged with an opponent, the character may suffer a number of strain up to their ranks in Leadership to allow an equal number of allies to immediately disengage from that opponent as an out-of-turn incidental.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NATCOMM', 'Natural Commando', 'Once per session, the character may reroll one Ranged (Light) or Stealth check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STANDFIRM', 'Stand Firm!', 'Once per encounter, the character may take the Stand Firm! action, making a [B]Hard ([DI][DI][DI]) difficulty Leadership check[b]. If the check is successful, the character chooses one ally within medium range for each [SU] on the check. Until the end of the encounter, chosen allies increase their wound threshold by an amount equal to the character''s Presence rating. (Multiple uses of this talent are not cumulative.)', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STANDFIRMIMP', 'Stand Firm! (Improved)', 'Allies affected by Stand Firm! also increase their strain threshold by an amount equal to the character''s Presence rating. (Multiple uses of this talent are not cumulative.)', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTORDER', 'Master of the Order', 'The character may spend two Destiny Points during a single action.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('TACTEVA', 'Tactical Evasion', 'Upgrade the difficulty of any ranged combat checks targeting the character a number of times equal to the number of maneuvers the character has performed to move during the current round.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FLOWALL', 'Flows Through All Things', 'Once per round, the character may perform the Flows through all Things maneuver to recover strain equal to their Force rating.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PRACSTRAT', 'Practiced Strategist', 'Once per session during a mass combat or combat encounter, the character may take the Practiced Strategist action, making an [B]opposed Knowledge (Warfare) versus Knowledge (Warfare) check[b] targeting the leader of the enemy forces. If the check succeeds, the character (or player) reveals a narrative advantage provided by their strategic planning, such as the timely arrival of reinforcements, sabotage of the enemy''s equipment, or a spy planted within the enemy ranks. The exact nature of the revelation is ultimately at the GM''s discretion, but it should provide the character and their allies with a significant advantage in the encounter or session.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PREEMPTINTER', 'Preemptive Intervention', 'Immediately after an opponent moves to engage an ally within short range of the character, the character may spend one Destiny Point to engage that opponent as an out-of-turn incidental.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RAPIDFIRE', 'Rapid Fire', 'Before making a Ranged (Light) combat check using a weapon that does not have the Limited Ammo item quality, the character may perform the Rapid Fire incidental to add the Auto-fire item quality to the attack. After resolving the attack, the weapon runs out of ammo.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FORMTACT', 'Formation Tactics', 'The character may take the Formation Tactics action by making a [B]Hard ([DI][DI][DI]) difficulty Leadership check[b]. If successful, they may choose a number of allies within short range equal to [SU] generated. The difficulty of attacks against these allies is upgraded once until the end of the character''s next turn. The effects of this action do not stack.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENDURPRES', 'Enduring Presence', 'Once per session, the character may upgrade the ability of a Mass Combat check (if they are the commander of the acting force) or the difficulty of a Mass Combat check (if they are commander of the enemy force) even if the character is not present or is prevented from communicating with their troops.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('INSPIRKILL', 'Inspiring Kill', 'The character may spend one Destiny Point to perform an Inspiring Kill maneuver immediately after conducting a successful attack in which the target is incapacitated or suffers a Critical Injury. The character rolls [FO] no greater than their Force rating, and may spend [FP] to heal 2 strain from allies within medium range (and may do so multiple times). If the rules for Morality in [B]Force and Destiny[b] are in use, a character who has purchased this talent gains 1 Conflict at the beginning of each game session.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('FITES', 'Field Tester*', 'Remove [SE] per rank of Field Tester from checks made using equipment or vessels the character has repaired or improved this session.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KEEPTALKINGIMP', 'Keep Them Talking (Improved)', 'Once per encounter, may spend [TH][TH][TH] or [DE] from an opposed social check to add [SU][AD] to all checks targeting that character this encounter.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('QUICKWITTED', 'Quick Witted', 'Once per session after failing a Deception or Stealth check, the character may reroll the check using Cool. The difficulty of the Cool check is the same as the original check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NODIE', 'No Time to Die', 'Once per session, as a maneuver, spend a Destiny Point to recover strain and/or wounds in any combination up to ranks in Cool or Discipline.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KEEPTALKING', 'Keep Them Talking', 'When opposing a social check, may substitute Cool instead of Discipline or Vigilance.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('USERTALENT3', 'Tools of the Tradecraft', 'The character may spend a Destiny Point, upon doing so they may declare that an item in their possession has a secret secondary use or feature. Players and GMs are encouraged to treat this like a Gear Attachment as per page 58 of Cyphers and Masks, but GM has final say on the device and its usage. The item doesn’t need to be an actual declared item but could be something they would have on them like a chronometer. If secondary use is as a weapon, it counts as an improvised weapon.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SUAVESOPH', 'Suave And Sophisticated', 'May suffer 2 strain to make a Deception check with Presence instead of Cunning.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANIMALHANDLEIMP', 'Animal Handler (Improved)', 'Once per round, the character may suffer 1 strain to perform the Animal Handler maneuver as an incidental. Additionally, the range of Animal Handler extends to medium.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISARMINGPERSIMP', 'Disarming Personality (Improved)', 'Once per encounter, the character may suffer 3 strain to add :success::advantage: to a check made to a social or combat check made to disarm a foe.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LIVINGHOLOCRON', 'Living Holocron', 'Once per session as an action, roll [FO] no greater than Force rating. Spend [FP] to decrease the difficulty of all knowledge checks made this encounter once, to a minimum of [B]Easy ([DI])[b].', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENCOURAGESUP', 'Encouraging Words (Supreme)', 'Once per session, when an ally within medium range would fail a check while benefiting from the character''s assistance, that ally may reroll the check using the character''s Charm or Leadership instead of the required skill.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMPTYSELFIMP', 'Empty The Self (Improved)', 'Once per encounter, the character may decrease the difficulty of a check affected by Empty The Self once.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMPTYSELF', 'Empty The Self', 'Once per round, suffer 2 strain and perform the Empty The Self maneuver to remove [SE][SE] from the next check they make this round.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('BLOCK', 'Block', 'When hit by a melee attack, suffer 3 strain to reduce damage by 4. This talent may only be used once per hit and when the character is wielding a Melee or other appropriate item, per GM discretion.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNIVERSESUP', 'One With The Universe (Supreme)', 'Once per session, the character may suffer strain up to their ranks of Astrogation to treat that many [DA] as if they were [LI], or that many [LI] as if they were [DA].', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ENCOURAGEIMP', 'Encouraging Words (Improved)', 'Once per round when an ally benefiting from the character''s assistance succeeds on a check, the character and that ally recover one strain. Additionally, the range of Encouraging Words is increased to medium.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOOTHIMP', 'Soothing Presence (Improved)', 'The character may spend [FP] on strain recovery checks to have the character or the chosen ally recover one wound. [FP] generated from [DA] inflicts strain on all healed allies.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOOTHSUP', 'Soothing Presence (Supreme)', 'When the character spends [FP] to heal an ally’s wounds and/or strain during strain recovery checks effects, they heal a number of allies equal to their Willpower instead. Once per session, per GM discretion, the character may spend [FP][FP][FP] to reduce the current amount of conflict being suffered by all affected allies by 1.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('CONDEMNATION', 'Condemnation', 'Once per encounter, the character may make an [B]opposed Discipline vs Cool combined Force check[b] against a target within short range, learning their true intent and character. On success, the target adds [TH] to all social checks they make this encounter, plus an additional [TH] for each [SU][SU] past the first. Spend [AD][AD] or [TR] to add [FA] to those checks. Spend [FP] to inflict one strain for each [FP] spent this way.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANIMALHANDLER', 'Animal Handler', 'Once per round as a maneuver, the character may suffer strain no more than their ranks in Animal Handler. Upgrade the ability of the next check made by a friendly creature within short range a number of times equal to strain suffered.', 'taManeuver', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNIVERSEIMP', 'One With The Universe (Improved)', 'Spend [AD][AD][AD] or [TR] from One With The Universe to add [SU] to each combined Force check the character makes this encounter.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ADVICEIMPROVED', 'Sage Advice (Improved)', 'When taking the Sage Advice action, the character may spend [AD][AD] or [TR] to decrease the difficulty of the next check made by an additional ally once per [AD][AD] or [TR] spent.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GREATESTTEACHER', 'The Greatest Teacher', 'Once per encounter after failing a skill check, the character may suffer 4 strain to add [TR] to the next check the character or an ally within medium range makes using that skill.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('HARMONYBEING', 'Harmonious Being', 'Once per round, when targeting an ally with a Force power or Force Talent, may suffer 2 strain to add [DA] or [LI] to the pool.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('KNOWLEDGESUM', 'The Sum of All Knowledge', 'Once per encounter after failing a Knowledge check, may reroll the check using a different Knowledge skill, increasing the difficulty of the check twice.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('WELLROUNDIMP', 'Well Rounded (Improved)', 'Once per session, the character may spend a Destiny Point to treat their skill ranks in a career skill as if it were one rank higher (to a maximum of 5) until the end of the encounter.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STUBBORNBANTHA', 'Stubbon Like A Bantha', 'Once per session, the character may spend a Destiny Point and choose a friendly non-sentient creature within short range. The character’s Brawn and soak becomes equal to that creature’s Brawn and soak for rounds equal to the character’s ranks in Resilience until the end of the encounter.', 'taIncidentalOOT', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STARSALIGN', 'The Stars Align', 'Once per encounter as a maneuver, the character may commit one or more [FO]. On a later turn, the character may uncommit one or more [FO] committed this way to add [SU], [AD][AD], [LI], or [DA] for each [FO] uncommitted to a check made by an ally within medium range.', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('NERFWHISPER', 'Nerf Whisperer', 'Once per session, the character may make a [B]Hard ([DI][DI][DI]) Survival check[b]. On Success, they treat all friendly non-sentient creatures within medium range as the character’s Animal Companion until the end of the encounter, extending the benefits of all Animal Companion and related talents. When directing these animals while this effect is active, the character treats them all as if they were a single entity, per GM discretion.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SCRUFFY', 'Scruffy', 'Add [BO] to Athletics and Resilience checks the character makes per ranks of Scruffy.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SOOTHINGPRESENCE', 'Soothing Presence', 'May add [FO] no greater than Force rating to checks to recover strain. Spend [LI] to heal or have target ally recover 1 strain.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('GOODRELATIONS', 'Good Relations', 'Once per encounter, the character may suffer 2 strain to remove [DE], or [TH] equal to their ranks of Knowledge (Xenology), from a social check made by a character within short range. The character should justify this with cultural knowledge of one of the present parties.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('STARSALIGNIMP', 'The Stars Align (Improved)', 'When uncommitting [FO] committed to The Stars Align, may uncommit [FO][FO][FO] to add [TR] to an allied check.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('RESEARCHSUP', 'Researcher (Supreme)', 'Once per encounter, the character may spend a Destiny Point to make a Knowledge check as an incidental.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('VITALFORCE', 'Vital Force', 'Once per session when an ally within medium range exceeds wound threshold, may make a [B]Daunting ([DI][DI][DI][DI]) Medicine check[b]. The target recovers wounds equal to [SU]. Spend [AD][AD] or [TR] to have them not suffer a critical injury.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNARMEDBLOCK', 'Unarmed Block', 'May Block while unarmed. Reduce strain cost to Block while unarmed by 1 (to a minimum of 1).', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PURIFICATION', 'Purification', 'The character may make an [B]Average ([DI][DI]) Knowledge (Xenology) check[b], adding [FO] no greater than Force rating. On success, the character may spend [FP] to remove a status condition from an ally within short range for every [FP] spent this way. If the ally is poisoned, the difficulty to purify is the original difficulty to resist the poison. Alternatively, this action may be used to purify food or water, rendering it safe to consume.', 'taAction', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNARMEDBLOCKIMP', 'Unarmed Block (Improved)', 'When a combat check made by an engaged foe generates [TH][TH][TH] or [DE], may disarm the attacker and may equip that weapon.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SAGEADVICE', 'Sage Advice', 'Once per encounter, the character may make an [B]Average ([DI][DI]) Charm check[b]. On success, reduce the difficulty of the next check made by an ally within medium range once.', 'taAction', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEEPUNDERSTAND', 'Deeper Understanding', 'Add [BO] per rank of Deeper Understanding to Astrogation and Knowledge (Lore) checks.', 'taPassive', true, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTERCURATOR', 'Master Curator', 'When making a Perception or Computers check to discover or recover information, suffer strain up to ranks of a Knowledge skill to add that many [BO] to the check.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISARMINGPERSSUP', 'Disarming Personality (Supreme)', 'Once per session after disarming or nonlethally incapacitating a foe, the character may spend a Destiny point to force a number of targets equal to twice the character''s Force rating to cease actively attacking or pursuing hostile intent. A target of a higher tier may not be swayed by a lower-tier NPC being disarmed or dispatched, per GM discretion. This ceasefire or parley may require subsequent checks to maintain, or may return to active hostilities.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('MASTERHEALER', 'Master Healer', 'Once per encounter while making a Heal Power check, may suffer 3 strain to apply the effects of the Physician and Surgeon talents.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DISARMINGPERSONALITY', 'Disarming Personality', 'The character removes [SE][SE] from called shot attacks to destroy the weapon, checks to remove them physically or with the Force, or Social checks to checks to convince the target to disarm.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNCONVENTSOL', 'Unconventional Solution', 'Once per session as a maneuver, choose a skill and make an [B]Average ([DI][DI]) Knowledge (Education) check.[b] The character may substitute a different characteristic when making checks using that skill this encounter.', 'taManeuver', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('SLYTOOKA', 'Sly As A Tooka', 'Once per encounter when making a Charm or Negotiation skill check, the character may use Cunning instead.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LIVINGHOLOIMP', 'Living Holocron (Improved)', 'The character may suffer 2 strain to perform the Living Holocron action as a maneuver. Additionally, spend [FP][FP][FP] instead of [FP] to decrease the difficulty of all knowledge checks they make by 2 instead, to a minimum of [B]Simple ()[b].', 'taManeuver', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ONLYFORCE', 'There Is Only The Force', 'Once per session when the character would be incapacitated, the character may spend a Destiny point to make a Force power check as an out-of-turn incidental. If it is successful, add [TR] to the result.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('EMPTYSELFSUP', 'Empty The Self (Supreme)', 'Once per session, the character may add [FO] to a check affected by Empty The Self no greater than their Force Rating, and may spend [FP] to add [SU] and/ or [AD] to the result, but only one of each symbol. Additionally, [FP][FP] may be spent to add [SU][AD] to the check.', 'taIncidental', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('ANIMALHANDLESUP', 'Animal Handler (Supreme)', 'The first time the character activates Animal Handler each round, the targeted creature recovers 2 strain. Additionally, the range of Animal Handler extends to long range.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('UNCONVENTSOLIMP', 'Unconventional Solution (Improved)', 'When performing the Unconventional Solution maneuver, an ally within medium range may also substitute a characteristic for skill of their choosing, and may choose a different characteristic for that skill.', 'taPassive', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('DEFLECT', 'Deflect', 'When hit by a ranged attack, suffer 3 strain to reduce damage by 4.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('PHYSIMP', 'Physician (Improved)', 'Once per encounter, the character may spend [AD][AD], [TR], or [FP][FP] from a Medicine or Heal Power check to have the target add [AD] equal to ranks of Physician to their next check.', 'taPassive', false, true, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
INSERT INTO ref_talents (key, name, description, activation, is_ranked, is_force_talent, dataset_source, is_retired) VALUES ('LONGSTORY', 'It''s A Long Story', 'Once per encounter, may suffer 2 strain to add [BO] equal to ranks of Knowledge (Lore) to a social check made to delay, distract, or confuse. Spend [AD][AD][AD][AD] or [TR] from that check to stagger the target.', 'taIncidental', false, false, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, activation = EXCLUDED.activation, is_ranked = EXCLUDED.is_ranked, is_force_talent = EXCLUDED.is_force_talent;
