INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREBASIC', 'Endure Basic Power', 'When the character suffers a Critical Injury with a severity rating no greater than [B]Easy ([DI])[b], the character may activate Endure as an out-of-turn incidental and commit [FO] to temporarily ignore the effects of that injury. The character does not apply results from the Critical Injury or add +10 to further rolls on the Critical Injury Result table while [FO] remains committed. When this ongoing effect ends, the character suffers all effects of the Critical Injury (unless it has been treated).', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
