INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREMASTERY', 'Mastery', 'When activating Endure, the character may make an Endure power check, making a Discipline check with a difficulty equal to the severity of the Critical Injury and adding [FO] up to the character''s Force rating. If the character succeeds on the check and generates [FP] equal to the Severity of the Critical Injury, the Critical Injury is not suffered.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
