INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('RANGEIMPALTERRE', 'Range (Improved)', 'When activating the Range upgrade, the Force User may instead extend the range of the effect to long range.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SPEEDALTERRE', 'Speed', 'Spend [FP][FP] after successfully activating the basic power to immediately perform a free Move maneuver as an incidental. This Move maneuver may be in addition to any other maneuvers performed this turn and can allow the character to perform three maneuvers in a turn.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STRENGTHALTERRE', 'Strength', 'Spend [FP] to exclude characters equal to current Force Rating. The user may activate this multiple times.', 'ALTER', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BATTLEDURATIONRE', 'Duration', 'Commit [FO][FO][FO] to sustain the effects of the power on affected targets while they remain in range.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('DURATIONIMPBATTLE', 'Duration (Improved)', 'Commit [FO][FO] to sustain the effects of the power on affected targets while they remain in range instead of [FO][FO][FO].', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGNITUDEBATTLERE', 'Magnitude', 'Spend [FP] to increase the number of targets affected by an amount equal to the User''s Presence multiplied by the number of Magnitude upgrades purchased. The user may activate this multiple times, increasing the number of targets by this number each time.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MASSCOMBATBATTLE', 'Mass Combat', 'The user may add [FO] no greater than Force rating to Mass Combat checks. Spend [FP][FP][FP] to add [SU] to the results. This may be activated multiple times.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MASTERYBATTLERE', 'Mastery', '[B]Unify[b]: Once per session while this power is active, when an affected ally makes a Force Power check or a combined Force check, the user and any number of affected allies may suffer 2 strain and commit [FO]. For each that does, the ally adds an additional [FO] to the check. Afterwards, the Battle Meditation power ends.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BATTLERERANGE', 'Range', 'Spend [FP] to increase power''s range by 1 range band, to maximum of extreme range. This may be activated multiple times.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SHAREDTAKEN', 'Skill Shared / Skill Taken', '[B]Unify[b]: If no [DA] were used to generate [FP], choose one skill. While affected by the power, each affected character counts as having the same number of ranks in the chosen skill as the affected character with the most ranks in the skill.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STRENGTHBATTLERE', 'Strength', '[B]Unify[b]: Spend [FP] to add [SU] instead of [AD]. This may not be activated multiple times.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STRENGTHIMPBATTLE', 'Strength (Improved)', '[B]Unify[b]: Spend [FP][FP] to add an additional [SU].
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('RANGEIMPBATTLERE', 'Range (Improved)', 'Spend [FP][FP] to change the range of the power and range upgrade to planetary scale. The user suffers 3 stran at the beginning of each of their turns while Battle Meditation is active using this upgrade.', 'BATMED', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BINDBARE', 'Bind: Basic Power', 'The user may spend [FP] to immobilize a target for or simple, inert object with a silhouette of 1 or less within short range until the end of the user''s next turn. If the user used a [DA] to generate [FP], the target suffers 1 wound per [FP] spend on the check (ignoring soak). Any character or object immobilized in this way cannot be moved unless an [B]opposed check vs the character''s Discipline[b].', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BOUNDAGGRO', 'Bound Aggression', 'Once per encounter after a foe makes a successful attack but before it deals damage, the user may suffer 3 strain to use Bind on the attacker as an out-of-turn incidental. Spend additional [FP] to add that many [FA] to the result of the check.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONFOUNDBIND', 'Confounding Bindings', 'The user may spend [FP] to add [SE][SE] to checks made by all affected foes for the duration of this power.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('DURATIONBINDRE', 'Duration', 'The power gains the ongoing effect: Commit [FO][FO][FO] after successfully activating the basic power. If a target was immobilized or staggered by this power, they remain immobilized or staggered as long as three Force dice remain committed and the target stays within range. If a target moves beyond the range of the power, the effects end for that target, but not for any other targets of the power. The user may not activate this multiple times.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORCETRACTOR', 'Force Tractor', 'After successfully activating the basic power targeting a starship or vehicle, treat it as if it were affected by the Tractor quality for the duration of the power, except that checks to escape the tractor are opposed by the user''s Discipline. If [DA] was used to generate [FP], the target suffers 1 system strain per [FP] generated on the check.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGNITUDEBINDRE', 'Magnitude', 'Spend [FP][FP] to affect 1 additional target within range. The user may activate this multiple times, increasing the number of targets by this number each time.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGNITUDEIMPRE', 'Magnitude (Improved)', 'When the user activates the Magnitude upgrade, they instead affect additional targets equal to half the user''s Willpower, rounded up.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MASTERYBINDRE', 'Mastery', 'When using Bind, if otherwise unopposed, may make an [B]Opposed Discipline vs. Resilience check[b] as a part of the pool against a target. On success, if no [DA] were used to generate [FP], immediately stagger that target until the end of their next turn. If any [DA] were used to generate [FP] and the check succeeds, the target also suffers a Critical Injury, adding +10 per [FP] spent on the check.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('OPPRESSIVESTASIS', 'Oppressive Stasis', 'Spend [FP]. Whenever a target affected by Bind takes an action, that target suffers strain equal to Willpower.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('POWERFULSTASISRE', 'Powerful Stasis', 'When using the Bind Power, the user may make a [B]Discipline check[b] as part of the pool. On success and power activation, they may immobilize a powerful and/or complex object, such as a waterfall or a spinning mechanism. The difficulty of the check is determined by the size and power of the target.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('RANGEBINDRE', 'Range', 'The user may spend [FP] to increase power''s maximum range bands by one, to maximum of Extreme. This may be activated multiple times.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('RANGEIMPBINDRE', 'Range (Improved)', 'When the user activates the Range upgrade, they increase the maximum range band of the power by two instead of 1.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STRENGTHBINDRE', 'Strength', 'Spend [FP] to increase the maximum silhouette of targets by 1, to a maximum of 4. This may be activated multiple times.', 'BIND', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MOVEBARESPEC', 'Move Basic Power', 'The Force user can use the Force to lift small objects and willing beings via the power of the Force:
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EXTRICATE', 'Extricate', 'The user gains the ability to pull objects off secure mountings or from an opponent''s grasp.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FLOATINGBULWARK', 'Floating Bulwark', 'After successfully activating the base power, the user may commit a number of [FO] up to the greatest silhouette among target objects to use objects of equal silhouette as cover, the user gains ranged defense equal to the silhouette. Per GM discretion, silhouette 3 or greater cover may make attacking the user or attacks from the user''s position impossible, and may protect engaged characters. An additional character may be defended per each additional target object, as long as they stay within the maximum range of the power. The objects remain as long as [FO] remains committed.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGNITUDEMOVERE', 'Magnitude', 'The user may spend [FP] to increase targets affected by 1. The user may activate this multiple times.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGIMPRE', 'Magnitude (Improved)', 'When activating the Magnitude upgrade, the user may spend additional [FP][FP] to increase the number of targets by half the user''s Willpower, rounded up, instead of 1.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MOVEMASTERYRE', 'Mastery', 'The user may spend [FP] to use the Move power on non-willing living beings as if they were objects, including as objects to hurl at other foes, dealing damage to both. If only [LI] were used to generate [FP], the user may have any damage dealt by Move to be treated as strain damage. If only [DA] were used, all targets of Move attacks suffer a critical injury, adding +10 times the user''s Willpower to the results.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PRECISECONTROL', 'Precise Control', 'The user may finely manipulate objects, allowing them to do whatever they could normally do with their hands to a held item. If this power is used to manipulate something such as a datapad or computer terminal, the controls count as a silhouette 0 object.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PUSH/PROPEL', 'Push / Propel', 'The Force user can choose to either hurl objects to damage targets, or hurl blasts of Force directly at targets by making a [B]ranged combat check using the Discipline skill[b] combined with a Move power check, but must still spend enough [FP] to move the object or target:
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('RANGEMOVERE', 'Range', 'The user may spend [FP] to increase power''s range by 1 range band, to a maximum of Extreme. The user may activate this multiple times.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('RANGEIMMOVERE', 'Range (Improved)', 'The user may spend [FP] to increase the power''s range by 1 range band, to a maximum of Extreme. The user may activate this multiple times.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SPEEDMOVERE', 'Speed', 'Once per encounter before or after a character acts, the user may suffer 3 strain to use the Move power as an out-of-turn incidental, may not make an attack. The user may target a foe within range with the basic power to interfere with an action. If that action was not an opposed check, it becomes opposed by the user''s Discipline.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STRENGTHMOVERE', 'Strength', 'The user may spend [FP] to increase silhouette able to be targeted by 1, to a maximum Silhouette equal to the user''s Willpower.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STRENGTHIMPMOVERE', 'Strength (Improved)', 'The first time the user activates Strength each round, increase silhouette able to be targeted by 2 instead.', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STRENGTHSUPMOVERE', 'Strength (Supreme)', 'Once per session when activating the Strength upgrade, the user may spend [FP][FP] instead to increase the silhouette able to be targeted by user’s Willpower, to a maximum of Silhouette 5 (this supersedes previous maximums).', 'MOVE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCEBARE', 'Enhance Basic Power', '[B]Take a Force Leap Action:[b] Make an Enhance power check. The user may spend [FP] to jump to any location within short range, both horizontally and vertically, and may be used to leap over obstacles.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('COMBATMORE', 'Combat Momentum', 'Once per encounter, after using Force Leap to engage a foe, the next attack the user makes this round against that foe ignores that foe''s melee defense.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONTROLLEDFALLRE', 'Controlled Fall', 'When making a check to reduce fall damage, may make an Enhance force check as part of the pool. The user may spend [FP] to decrease the fall by one range band.  The user may activate this multiple times. If the fall is reduced to less than short, the user suffers no effects from falling. Any falls longer than Planetary Short are treated as Planetary Short.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EMPAGILITYRE', 'Enhanced Agility', 'As a maneuver, commit [FO]. The user increases their Agility characteristics by 1 (to a maximum of 6).', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EMPBRAWRE', 'Enhanced Brawn', 'As a maneuver, commit [FO]. The user increases their Brawn characteristics by 1 (to a maximum of 6).', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCEATHRE', 'Enhanced Athletics', 'When making an Athletics check, the Force user may roll an [B]Enhance power check[b] as part of the pool. The user may spend [FP] to add [SU] or [AD] to the results. Each symbol may only be added once.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BRAWLRE', 'Enhanced Brawl', 'Enhance can be used with the Brawl Skill.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCECOORDRE', 'Enhanced Coordination', 'Enhance can be used with the Coordination skill.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PILOTINGENRE', 'Enhanced Piloting', 'Enhance can be used with the Piloting (Planetary) or Piloting (Space) skills.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MASTERYENRE', 'Mastery', 'Once per session when making a combined [B]Enhance power check[b], the user may spend [FP][FP][FP] to immediately take another action.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('RANGEENRE', 'Range', 'Spend [FP] to increase Force Leap''s range by one range band, to a maximum of Medium.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SPEEDENRE', 'Speed', 'The user may perform Force Leap as a maneuver instead of as an action.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SPEEDIMPENRE', 'Speed (Improved)', 'Once per encounter, immediately before or after a character acts, suffer 3 strain to perform Force Leap as an out of turn incidental.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STRENGTHENRE', 'Strength', 'Spend [FP][FP] to add [SU][AD] to a [B]combined Enhance power check[b], separately and in addition to the Basic Power. The user may activate this multiple times.', 'ENHANCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INFLUBPRE', 'Influence Basic Power', 'The character may attempt to guide, shape, and even dominate the thoughts and feelings of others:
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BEGUILINFLUENCERE', 'Empowered Deception', 'When making a Deception check, the user may roll an [B]Influence power check[b] as part of the dice pool, and may spend [FP] to gain [SU] or [AD] on the check, but only one of each symbol.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CAPTIINFLUNCERE', 'Empowered Charm', 'Influence can be used to make combined Charm power checks.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CLOUDEDMINDRE', 'Clouded Mind', 'Spend [FP][FP] to add [FA] to each check made by each target for the duration of Mind Trick. This may be activated multiple times.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('COMMANDINRE', 'Empowered Leadership', 'Influence can be used to make combined Leadership checks.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('DURATIONINRE', 'Duration', 'The user may commit [FO][FO] after the successful activation of the power to maintain the effects of Mind Trick for as long as they remain committed, or until the end of the current encounter. If a target becomes out of range of the power, the effect persists until the end of their next turn.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENTINRE', 'Empowered Negotiation', 'Influence can be used to make combined Negotiations power checks.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGINRE', 'Magnitude', 'The user may spend [FP] to choose additional targets equal to the user''s Force rating.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGINIMPRE', 'Magnitude (Improved)', 'When activating the Magnitude upgrade, spend [FP][FP][FP] instead to affect any number of characters within range. How this affects a large number of characters is up to GM discretion.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MASTERYINFRE', 'Mastery', 'Once per session, spend a number of [FP] depending on NPC type. If no [DA] were spent, the target of Mind Trick is completely pacified. If no [LI] were spent, they are sent into a violent rage or terrified stupor. The user may effect a minion group by spending [FP], a rival by spending [FP][FP], or a Nemesis whose current strain is greater than half of their strain threshold by spending [FP][FP][FP][FP]. How the character behaves in this state is GM discretion., but their role should meaningfully change their role, or be removed entirely, from the encounter.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MENACINGINFLUENCE', 'Empowered Coercion', 'Influence can be used to make combined Coercion power checks.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('RANGEINFRE', 'Range', 'The user may spend [FP] to increase the maximum range of the Influence power by one range band, to a maximum of extreme.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INFRANGEIMPRE', 'Range (Improved)', 'When activating the Range upgrade, increase the maximum range by two range bands instead of one.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUBDUEUPLIFT', 'Subdue / Uplift', 'Spend [FP] to have the targets suffer or recover a number of strain equal to the user''s Force rating.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STRENGTHINFRE', 'Strength', 'Spend [FP][FP] to add [SU][AD] to a [B]combined Influence power check[b] using a social skill, separately and in addition to the Basic Power. The user may activate this multiple times.', 'INFLUENCE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SENSEBARE', 'Sense Basic Power', 'The Force user can sense the Force interacting with the world around them, allowing them to sense being and the emotions in the following ways:
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('DURATIONSERE', 'Duration', 'Sense''s ongoing effects may be triggered one additional time per round.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ESCAPEDANGERSENSE', 'Escape Danger', 'When Threat Sense triggers, the user may spend 2 strain to make a Move maneuver as an out-of-turn incidental after the triggering attack has been resolved.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGSENSERE', 'Magnitude', 'Spend [FP] to increase the number of targets affected by power equal to the user''s current Force Rating. The user may activate this multiple times.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGIMPROVEDSENSERE', 'Magnitude (Improved)', 'When activating the Magnitude upgrade, the user may instead spend [FP][FP][FP] to affect all characters within range of the power.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MASTERYSENSERE', 'Mastery', 'Once per session, make a [B]Sense power check[b] combined with an [B]opposed Discipline vs. Discipline check[b] against a living target within range. If the check succeeds, spend [FP] to ask the GM a number of simple questions that the target''s mind could answer equal to [FP] spent this way. If [FP] generated from [DA] were spent, the target suffers strain equal to total [FP] spent on the power.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PROTECTIVEINSTINCTS', 'Protective Instincts', 'When an ally engaged with the user becomes the target of an attack while committing [FO] to Threat Sense, the user may choose to upgrade the pool of the check as if they were being attacked. This counts against the number of times Threat Sense can trigger each round.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('RANGESENSERE', 'Range', 'Spend [FP] to increase the power''s range by one range band.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('RANGEIMPSENSERE', 'Range (Improved)', 'When activating the Range upgrade, increase the maximum range by 2 instead of 1.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SENSEOPENINGRE', 'Sense Opening', 'Ongoing effect: As a maneuver, commit [FO]. Once per round, when the Force user makes a combat check, upgrade the ability of the pool once.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
