INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SURFACEREADING', 'Surface Reading', 'Spend [FP] to sense the current thoughts of one living target whom the user is engaged with. This effect does not benefit from the Magnitude upgrade. The user may activate this multiple times.', 'SENSE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
