INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ONENESSEBB', 'Oneness of the Force', 'The first time the user successfully activates the Basic Power of Ebb/Flow each session, they add a Light Side Point to the Destiny Pool.', 'EBBFLOW', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
