INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('DANGEROUSWEAP', 'Dangerous Weapon', 'The Force user gains the ability to imbue a created weapon with certain offensive qualities that might manifest as a palpable darkness around the item, a keening wail whenever the weapon is swung, or ethereal green flames. Spend [FP] to grant one conjured weapon one of the following qualities: Burn 3, Pierce 3, or Vicious 3. The user can activate this multiple times, granting the weapon an additional quality each time (but may not grant the same quality more than once).', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJDURATIONRE', 'Duration', 'After successfully activating the Basic Power, the user may commit [FO] to sustain a single conjured weapon or tool while it remains in Short Range. The user may commit additional [FO] to sustain additional conjured items and tools this way.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJDURIMPRE', 'Duration (Improved)', 'The user may commit [FO][FO] after successfully activating the Mastery to sustain a conjured creature or item while it remains within medium range. The user may activate this multiple times.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EMPIMPLEMENT', 'Empowered Implement', 'The user may spend [FP][FP] to add [SU][AD] to the first check made using the conjured item, or made by the conjured creature.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('IMBUIMPLEMENT', 'Imbued Implement', 'The user may spend [FP][FP] to increase another Force user''s Force Rating by 1 while they wield an item conjured by the character.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJMAG', 'Magnitude', 'Spend [FP][FP] to conjure an additional tool, weapon, or conjured creature. The user may choose different effects from activated upgrades for each object conjured. The user may activate this multiple times.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJMASTERYRE', 'Mastery', 'Ongoing effect: Instead of activating the Basic Power, the user may spend [FP][FP][FP] to conjure a facsimile of a Silhouette 1 creature instead of an object. This creature is mindlessly bound to the user''s will, and mindlessly follows the user''s command until the end of the user''s next turn, at which point it will dissipate. This creature using the profile of a living minion NPC of the user''s choice, except they have the following attack profile: (Brawl or Melee; Damage +5; Critical Rating 3; Range [Engaged]; Cortosis). Upgrades that affect conjured weapons affect this attack. Once per round, the user may perform a maneuver to grant the conjured creature a maneuver and an action.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MERCYCRUELTY', 'Mercy / Cruelty', 'If no [DA] were spent, the user may increase the conjured weapon''s (or conjured creature''s attack) damage by 5 and have it gain the Stun Damage quality. If no [LI] were spent, reduce the weapon''s (or conjured creature''s attack''s) critical rating by 1.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PERFECTEDFORM', 'Perfected Form', 'Weapons, tools, and other objects the user conjures appear genuine and accurate to the form they represent. A perception check with a difficulty equal to the user''s Force Rating is required to determine its falsity. Additionally, a wielder of the user’s conjured weapon may make attack checks using the Lightsaber skill, and may be used with the Reflect or Deflect talents.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PROTECTIVEWEAPON', 'Protective Weapon', 'The Force user gains the ability to imbue a created weapon with certain defensive qualities, which might manifest around the item as a blurred protective aura, a form that twists and shifts to protect the wielder, or a halo of crackling energy. Spend [FP] to grant one conjured weapon one of the following qualities: Defensive 1, Deflection 1, or Stun 4. The user can activate this multiple times, granting the weapon an additional quality each time (but may not grant the same quality more than once).', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJRANGERE', 'Range', 'The user may spend [FP] to extend the range at which conjured objects may be maintained by the user by 1 range band. The user may activate this multiple times.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJRANGEIMPRE', 'Range (Improved)', 'When the user activates the Range upgrade, increase the maximum range within which a user may sustain a construct by 2 range bands instead of 1.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJSPEEDRE', 'Speed', 'Once per encounter, the user may spend 3 strain to activate the basic power as an incidental to conjure a tool or weapon.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONJSTRENGTHRE', 'Strength', 'The user may spend [FP][FP] to increase a conjured object''s encumbrance by 1 and damage by 3 if it is a weapon, or increase its silhouette by 1 and damage by 5 if it is a conjured creature.', 'CONJURERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SHATTERPOINTRE', 'Shatterpoint', 'The power gains the ongoing effect: as a maneuver, commit [FO][FO][FO]. The user’s  attacks gain Pierce with a rating equal to Cunning plus their ranks in Perception. If the character is using a starship or vehicle weapon and the Pierce rating is less than 10, increase Breach rating by 1.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKERSSIGHT', 'Seeker''s Sight', 'As a maneuver, commit [FO]. Upgrade the ability of Vigilance and Perception checks once.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKDURRE', 'Duration', 'The user may commit [FO] after successfully activating the base power to continue tracking or remove [SE] imposed due to cover, concealment, defense, or illusory effects from attacks against a target even when it moves.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKMAGRE', 'Magnitude', 'Spend [FP] to track or remove [SE] from attacks targeting one additional target.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKMASTERRE', 'Mastery', 'The user scans the target with their mind, following the flow of energy to the flaw that will be their undoing. The user may spend [FP][FP][FP] to add [TR] to combat checks they make against and checks they make to track or chase against one target of Seek while the power is active.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKSTRENGTHRE', 'Strength', 'The user may spend [FP] to gain additional details about the target’s location or direction, or remove additional [SE] from attacks the user makes against a personal-scale target equal to the user’s Force rating. The nature and type of details are per GM discretion, such as sensation, sounds, smells, or Force visions. Alternatively, the user may spend [FP][FP] to remove additional setbacks from attacks the user makes against a starship or vehicle target equal to the user’s Force rating instead.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKTRUTH', 'Seek Truth', 'The user may make an [B]Average ([DI][DI]) Perception or Vigilance check (or opposed Perception or Vigilance vs Deception)[b] to see through all sensory misdirections confronting them, whether from  technology or more esoteric means. This power dispels cloaking fields, holograms, Force Illusions, and even physical disguises, but does not reveal the truth of spoken or written lies. If the check is successful, the user may spend any number of [FP] to see through that many illusory effects.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKUNKNOWN', 'Seek the Unknown', 'When activating the Basic power, may instead spend [FP] instead of [FP][FP] to gain insight into lost or unknown people’s location or direction.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKMAGIMPRE', 'Magnitude (Improved)', 'When activating Magnitude, the user tracks or removes [SE] from additional targets equal to Force Rating instead.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKSPEEDRE', 'Speed', 'Once per encounter, the user may spend a Destiny Point to perform the Seek Power as a maneuver. If the user does, they may not activate the Seek power again this round.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEEKSTRIMPRE', 'Strength (Improved)', 'When activating Strength, additional details gained to track a character are of a type of the user’s choice rather than the GM’s. If more [SE] imposed by concealment, cover, defenses, or illusory sources would be removed from the user’s check to attack a target than there are [SE] on the check, add [BO] equal to the difference to the next attack the user makes against the target.', 'SEEK', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREBARE', 'Endure Basic Power', 'When the Force user suffers a Critical Injury with a severity no greater than [B]Easy ([DI])[b], the user may activate Endure as an out-of-turn incidental, committing [FO]. While the [FO] remains committed, the character ignores the effects of that Critical Injury, including adding +10 to further rolls on the Critical Injury Result table. The injury can still be healed while it is being ignored. When this ongoing effect ends, the character suffers all effects of the Critical Injury (unless it has been healed). If this Critical Injury is a result of being incapacitated, the user may still commit [FO] to activate Endure, but the effect ends at the end of the encounter if the user remains incapacitated.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDURESCARS', 'Endure Scars', 'As an incidental, the user may activate Endure to temporarily ignore the effects of a previously suffered Critical Injury.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREMAGRE', 'Magnitude', 'The user may commit one additional [FO] to temporarily ignore the effects of one additional Critical Injury while the [FO] remains committed. Endure must be separately activated for each Critical Injury.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREMASTRE', 'Mastery', 'Once per Session, the user can use Endure to temporarily ignore the Critical Injury result of Dead. The difficulty of the Dead Critical Injury is considered to be [B]Formidable ([DI][DI][DI][DI][DI])[b] when avoiding suffering it or healing it through any means.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDURESTRRE', 'Strength', 'The user can use Endure to temporarily ignore the effects of Critical Injuries with a Severity of [B]Medium ([DI][DI])[b].', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('OVERCOMEELEMENT', 'Overcome Elements', 'As an incidental, the user may commit one or more [FO] to temporarily ignore hostile the effects of environments with rating less than twice the number of [FO] committed this way. Alternatively, the user may commit [FO][FO][FO] to ignore the effects of vacuum, atmospheric pressure, or drowning.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EMPOWEREDRESIL', 'Empowered Resilience', 'When making an Resilience check, the Force user may roll an Endure power check as part of the pool. The user may spend [FP] to add [SU] or [AD] to the results. Each symbol may only be added once.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('OVERCOMEINJURY', 'Overcome Injury', 'Once per encounter when suffering a critical injury, the user may make an Endure power check and roll a Resilience check with a difficulty equal to the severity of the Critical Injury as part of the Pool. If the user succeeds, they may spend [FP] equal to the Severity of the Critical Injury to not suffer the Critical Injury.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREEXHAUST', 'Endure Exhaustion', 'As an incidental, the user may commit [FO] to temporarily ignore the negative effects of exhaustion, hunger, or thirst. If at any point the user ceases committing [FO] to this upgrade, the negative effects immediately resume.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('OVERCOMEWEAKNESS', 'Overcome Weakness', 'Once per encounter while suffering a status effect, as a maneuver, make an Endure Power check. Spend [FP][FP] to end a status effect the character is suffering. Status effects may include but aren''t limited to Immobilized, Restrained, Poisoned, Staggered, Burned, Disorient. The user may perform this maneuver even while immobilized or suffering another restrictive status condition.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDUREMAGIMPRE', 'Magnitude (Improved)', 'The user may commit additional [FO] to temporarily ignore a number of Critical Injuries up to the user’s Brawn, rather than one additional Critical Injury. Endure must be separately activated for each Critical Injury.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDURESTRIMPRE', 'Strength (Improved)', 'The user can use Endure to temporarily ignore the effects of Critical Injuries with a Severity of [B]Hard ([DI][DI][DI])[b]. Additionally, when activating Empowered Resilience, the user may spend [FP][FP] to add [SU][AD] to the check, and may do so multiple times.', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENDURESTRSUPRE', 'Strength (Supreme)', 'The user can use Endure to temporarily ignore the effects of Critical Injuries with a Severity of [B]Daunting ([DI][DI][DI][DI])[b].', 'ENDURE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIBPRE', 'Farsight Basic Power', 'The Force user expands normal visual senses through a connection to the Force. 
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ABSOLUTESIGHT', 'Absolute Sight', 'Spend [FP][FP] to see in every direction simultaneously, noticing and observing things in a full 360-degree arc. Add [BO][BO] to all Vigilance checks the user makes, and [SE][SE] to all Stealth and Skulduggery checks the user opposes, while the power is active.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('DISCERNSIGHT', 'Discerning Sight', 'The user may spend [FP] to make out fine details on a single object within medium range, or microscopic details on a single object within engaged range. Decrease the difficulty of any check the user makes to inspect or investigate this object once. The user may activate this multiple times.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EMPSIGHT', 'Empowered Sight', 'When making a Perception or Vigilance check, the Force user may roll an Farsight power check as part of the pool. The user may spend [FP] to add [SU] or [AD] to the results. Each symbol may only be added once.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PIERCINGSIGHT', 'Piercing Sight', 'The user may spend [FP] to see through one object within range as if it were transparent. Ignore the effects that cover, concealment, or defense this object would grant a target of a combat, Perception, or Vigilance check the character makes. The user may activate this multiple times.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SIGHTNOEND', 'Sight Without End', 'The user may spend [FP][FP]. The user can see as though from a spot within close range (planetary range) of the user’s body. This may be any direction from the user, horizontal and/or vertical.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTMASTER', 'Mastery', 'The user may spend [FP][FP][FP]. When making a Force power check, the user may treat any space that Farsight allows them to see as the originating point of the power. Which power checks or combined power checks this can apply to is up to GM discretion.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTDURATIONRE', 'Duration', 'The user may commit [FO] to sustain the effects of Farsight.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTRANGERE', 'Range', 'The user may spend [FP] to increase the range of the basic power by 1 range band. Additionally, increase the maximum range of Effortless Sight to long range. The user may activate this multiple times.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EFFORTLESSSIGHT', 'Effortless Sight', 'The user may treat their vision as if the Basic power is always active. To gain the benefit of any other upgrade, the user must activate the power as normal. Effects that limit or disrupt the user''s use of the force may affect this upgrade, per GM discretion.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SIGHTSOUND', 'Sight & Sound', 'Spend [FP] to choose a single source of sound within the range of Farsight. The user hears all sound that source creates as if it is at a conversational volume directed at them. The scope of a source could be an object, conversation, or individual, per GM discretion.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTRANGEIMP', 'Range (Improved)', 'When the user activates the Range upgrade, increase the maximum range of the power by two range bands instead of one. Additionally, increase the maximum range of Effortless Sight to extreme range.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTSPEED', 'Speed', 'Once per encounter, the user may perform the Farsight action as a maneuver. If the user does, they may not activate Farsight again this round.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FARSIGHTSTRENGTH', 'Strength', 'When activating Empowered Sight, the user may spend [FP][FP] to add [SU][AD] to the check, and may do so multiple times.', 'FARSIGHT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORESEEBPRE', 'Foresee Basic Power', 'The user may spend [FP] to gain vague hints of personal events to come in the following scene or encounter. Additional [FP] may be spent to increase the distance from the present moment the character may foresee, per GM discretion. For example, [FP][FP] may be spent to gain vague hints of the user’s coming day, whereas [FP][FP][FP][FP] may be spent to gain vague hints of the user’s coming week or fortnight.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONFFORESEEN', 'Strife Foreseen', 'When the user and/or allies make a skill check to determine initiative, the user may roll a [B]Foresee power check[b] as part of the pool. They may spend [FP] to add [SU] to their check or engaged ally''s check. When activating multiple times, the same character must be chosen.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANEUFORESEEN', 'Maneuver Foreseen', 'When performing a [B]Foresee power check[b] as part of an Initiative check, the user may spend [FP] to allow all affected targets to take one free maneuver before the first round of combat begins.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PROTECTPORTENT', 'Protective Portent', 'Affected targets increase their ranged and melee defense by 2 for the first round of combat.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONTINUITY', 'Continuity', 'Reduce the [FP] cost to activate the Basic Power by [FP], to a minimum of [FP].', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CLARITY', 'Clarity', 'The user may spend [FP] to pick out a specific detail from their vision. The user may activate this multiple times.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORMAGRE', 'Magnitude', 'The user may spend [FP] to affect an additional engaged ally (or themselves, if not the original target). The user may activate this multiple times.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORRANGERE', 'Range', 'The user may spend [FP] to increase the range at which they can affect their allies with the power by a single range band. The user may activate this multiple times.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORESTRRE', 'Strength', 'Once per check, if the user has gained specific details pertaining to the check they are making, they may suffer 2 strain to add [SU] to the result. How relevant the detail must be to the check it must be to qualify is per GM discretion.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FOREMAGIMPRE', 'Magnitude (Improved)', 'Once per [B]Foresee power check[b] when activating Magnitude, the user increases the number of engaged allies that are affected by the user’s Force rating instead of 1. Subsequent activations on the same check increase the number of affected allies by 1 as normal.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FOREMASTERY', 'Mastery', 'Once per session before a check is made, may spend [FP][FP] and make a [B]Hard ([DI][DI][DI]) Cool or Vigilance check[b] with a combined Foresee Force power check as an out of turn incidental. On success, the user may spend [FP][FP] to add [TR] or [DE] to that check. The user must establish what previously unestablished portent they have foreseen that caused this result.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORERANGEIMP', 'Range (Improved)', 'When activating the Range upgrade, the user may increase the maximum range by two range bands instead of 1.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('FORESTRENGTHIMPRE', 'Strength (Improved)', 'When the user activates Strength, they also [AD] to the check.', 'FORSEE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MENDMUT', 'Mend / Mutilate', '[B]Heal:[b] The user may make a [B]Heal power check[b] combined with a Medicine check with a difficulty chosen by the user. If the check succeeds, one target who heals wounds also heals one Critical Injury with a severity equal to or less than the difficulty of the Medicine check.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('HEALSPEED', 'Speed', 'Once per encounter, the user may suffer 3 strain to perform Heal or Harm as a maneuver. If the user does, they may not activate the power again this turn.', 'HEALHARM', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('HEALSTRENGTH', 'Strength', 'The user may spend [FP] to heal or inflict an additional number of wounds equal to the user''s Force rating or ranks in Medicine, whichever is higher. This effect may not be activated multiple times. Additionally, when activating Empowered Medicine, the user may spend [FP][FP] to add [SU][AD] to the check, and may do so multiple times.', 'HEALHARM', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
