INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EMPMEDI', 'Empowered Medicine', 'When making a Medicine check, or another check to help a living creature recover wounds, the Force user may roll an Heal power check as part of the pool. The user may spend [FP] to add [SU] or [AD] to the results. Each symbol may only be added once.', 'HEALHARM', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
