INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATESPEED', 'Speed', 'Once per encounter, the user may suffer 3 strain to perform Manipulate as a maneuver. If they do, they may not activate Manipulate again this turn.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
