INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANISTRIMP', 'Strength (Improved)', 'When activating the Strength upgrade, the Basic power heals or inflicts a number of strain equal to the user''s Intellect instead. Additionally, when activating Empowered Technopathy, the user may spend [FP][FP] to add [SU][AD] to the check, and may do so multiple times.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
