INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIRANGEIMP', 'Range (Improved)', 'When activating the Range upgrade, the user may increase the maximum range by two range bands instead of 1. Additionally, increase the maximum range of Reinforce Systems and Reinforce / Ruin by 2 range bands.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANISTRENGTHRE', 'Strength', 'Once per Power check, the user may spend [FP] to have the Basic power heal or inflict a number of strain equal to half the user''s Intellect, rounded up, instead.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
