INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MANIPULATEREMASTERY', 'Mastery', 'Once per encounter, when a droid or vessel suffers a Critical Injury or Critical Hit, the user may make a Manipulate Power check as an out of turn incidental. Spend one or more [FP] to increase or decrease the severity of the Critical Injury or Critical Hit by 10 per [FP] spent.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
