INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SYSTEMSREIN', 'Systems Reinforcement', 'As a maneuver, the user may commit one or more [FO]. Increase either the hull trauma or system strain threshold of an engaged vessel by 3 per [FO] committed. The user may commit to either effects any number or times in any combination.', 'MANIPULATE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
