INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('GREATERILL', 'Greater Illusion', 'The user may send [FP][FP] to obscure or create a number of additional illusions equal to their Cunning plus their ranks of Deception.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EMPMIS', 'Empowered Misdirection', 'When making a Deception or Skulduggery check to deceive others, the Force user may roll a Misdirect power check as part of the pool. The user may spend [FP] to add [SU] or [AD] to the results. Each symbol may only be added once.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISRANGERE', 'Range', 'The user may spend [FP] to increase power''s range by 1 range band. The user may activate this multiple times.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISSTRRE', 'Strength', 'The user may spend [FP] to increase the silhouette of the object obscured or illusion created by 1. The user may activate this multiple times.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISMASTERYRE', 'Mastery', 'Once per session may make an [B]opposed Deception vs. Vigilance check[b] against a beguiled target to have a created illusion make an action targeting that foe, or to add a [TR] to a social check made by a character who is benefiting from Mask of Deceit targeting that foe. If this action is an attack, it deals damage as strain, with base damage of 5 plus 3 for each Silhouette larger than 1. It has a critical rating of null, and a range appropriate to the illusion. For each additional illusion the user has conjured, add +1 to the damage.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISMAGNITUDE', 'Magnitude', 'Spend [FP] to affect additional targets equal to Cunning. The user may activate this multiple times.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MASKDECEIT', 'Mask of Deceit', 'Instead of merely hiding an object or person from the target with this power, the user may alter the appearance and sound of that object, person or creature, making it appear to be something or someone else to the target.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PERCEIVEUNREAL', 'Perceive the Unreal', 'Instead of hiding an object or person from the target with this power, the user may make an [B]opposed Deception vs. Vigilance check[b] as part of the pool. On success, may spend [FP] to cause the target to perceive an illusory object, person, or creature of Silhouette 1 or smaller where none exists. The user may create a sourceless sound instead, with a volume equivalent to the maximum silhouette of the power. If [DA] used to generate [FP], each target subjected to the unsettling illusion suffers 1 strain per [FP] spent on the check.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CONFOUNDAURA', 'Confounding Aura', 'As a Maneuver, commit one or more [FO]. Add [TH] per [FO] committed to combat checks targeting the user, and to Perception, or Vigilance opposed by the user.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDURATIONRE', 'Duration', 'After successfully activating the basic power, the user may commit [FO][FO] to sustain this power while the beguiled target remains in range. If a target moves beyond the range of a power, the effects end for that target.', 'MISDIRECT', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MISDIRECTBPRE', 'Misdirect Basic Power', 'The Force user creates illusions to fool those around them.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPSPEEDIMP', 'Speed (Improved)', 'Once per session before a foe makes a check, the user may spend 1 Destiny Point to perform Suppress at an out of turn incidental.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPRANGEIMPRE', 'Range (Improved)', 'When the user activates the Range upgrade, increase the maximum range of the power by two range bands instead of one.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPSPEED', 'Speed', 'Once per encounter, the user may suffer 3 strain to perform Suppress as a maneuver.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STILLNESS', 'Stillness', 'While the user has committed all of their [FO] they upgrade the ability of each check they make once. Force Power checks that commit [FO] as a result of the check after it is made do not benefit from this upgrade.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENSHROUD', 'Enshroud', 'Spend 1 Destiny Point to become undetectable via Force Powers, and make their own powers go unnoticed for the remainder of the encounter. The GM may determine certain uses of the Force, such as attacks or especially obvious displays, cannot be masked or go unnoticed.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('DEVOID', 'Devoid', 'Once per encounter, whenever a foe fails a Force power check or generates no [FP], the user may suffer 3 strain to add [DE] to the check.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('NULLIFICATION', 'Nullification', 'Suppress now affects all Force power checks made by foes within range instead of only hostile Force power checks targeting the user or their allies within range.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
