INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPSTRENGTHRE', 'Strength', 'The user may spend [FP] to add additional automatic [FA] to hostile Force power checks.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPPDURATIONRE', 'Duration', 'As a maneuver, the user may commit [FO] to sustain the ongoing effects of the Basic power on each affected target while they remain within range. If a target moves beyond the range of the power, the effects end for them but not for any other targets affected by the power.', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SUPMASTERYRE', 'Mastery', 'The user makes a Suppress power check along with an opposed [B]Discipline vs. Discipline check[b] targeting another Force user within short range. If the user spends [FP][FP] and succeeds on the check, the target immediately uncommits all [FO] and ends all ongoing Force powers and Force talents that required committed [FP]. 
