INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('TOTALSUPPRESSION', 'Total Suppression', 'As a maneuver, commit one or more [FO]. When a foe targets the user with a Force power, after the foe generates [FP], the user may reduce the total [FP] generated by 1 per [FO] committed (to a minimum [FP] of 0).', 'SUPPRESS', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
