INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('COMMUNEMASTERY', 'Mastery', 'Once per session, the user may spend [FP][FP][FP] to have a creature with silhouette no greater than the user’s Force rating, or a minion group of creatures with a silhouette not greater than half the user''s Force rating, rounded up, appear in the scene. If no [DA] was spent to generate [FP], the creature is friendly to the user. If [DA] was spent to generate [FP], the creature is neutral, and attacks a character of the GM’s choosing.', 'COMMUNE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('COMMUNEDURA', 'Duration', 'After successfully activating the Basic power, the user may commit [FO][FO] to maintain their connection to nature, or a creature while it remains in range. While committing, they may gain new or update known information as an incidental once during each future turn. 
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('COMMUNEMAG', 'Magnitude', '[B]With Creatures:[b] The user may spend [FP][FP] to affect an additional creature within range when communing or commanding.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('COMMANDCREATURE', 'Command Creature', 'Make an [B]opposed Survival vs. Discipline check[b] targeting a silhouette 0 creature within range as a part of the Commune power check. On success, may change the creature’s disposition towards the user one step, either from hostile to neutral or from neutral to friendly, and may spend [TR] to change the creature’s disposition from hostile to friendly. If the creature becomes friendly this way, the user may give them a simple command they will immediately abide to the best of their ability, performing a maneuver and taking an action.', 'COMMUNE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('ENHANCESURVIVAL', 'Enhanced Survival', 'When making a Survival check, the user may roll an Commune combined power check as part of the dice pool, and may spend [FP] to gain [SU] or [AD] on the check, but only one of each symbol.', 'COMMUNE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('COMMUNEBP', 'Commune Basic Power', 'The user can reach out with their feelings to connect with the animals and plants that surround them.
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('NATURALATTUNE', 'Natural Attunement', 'When activating the Basic power, the user may freely converse with an animal within range, or ask the natural world within range a single, simple question.', 'COMMUNE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PSYCHSTRENGTH', 'Strength', 'The user may spend [FP] to add [SU] to the next check they make that is relevant to their sensed experience. What is relevant is per GM discretion, but could be investigatory or interrogatory in nature.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STRENGTHIMPPSYCH', 'Strength (Improved)', 'When activating Strength, the user also adds [AD] to the affected check.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PSYCHMASTERY', 'Mastery', 'Once per session, the user may spend [FP][FP] to gain ranks in one skill possessed by a sensed character or the previous wielder of an engaged item until the end of the encounter. If the user possesses equal or higher skill ranks than the sensed character, increase their ranks in that skill by 1 instead. This chosen skill must be relevant to the event or person sensed, the object held, or the situation at hand, per GM discretion. Alternatively, the user may spend [FP][FP][FP] to temporarily gain access to a Force Power of the sensed character instead, including all non-Mastery upgrades sensed the character had, until the end of the encounter.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PSYCHSPEED', 'Speed', 'Once per session, the user may spend a Destiny Point to use the Psychometry power as an out-of-turn incidental.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGPSYCH', 'Magnitude', 'The user may spend [FO] to sense an additional experience from a character, object, or scene, and may do so multiple times.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('MAGIMPPSYCH', 'Magnitude (Improved)', 'Once per check when the user activates the Magnitude upgrade, the user senses additional images, sounds, or emotions equal to the user''s Force rating instead.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PSYCHDURATION', 'Duration', 'Commit [FO][FO] to maintain the effects of Psychometry.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('DURATIONIMPPSYCH', 'Duration (Improved)', 'Once per round while committing to Duration, the user may spend 2 strain to sense another image, sound, or emotion as an incidental, or increase the clarity of a previously sensed image, sound, or emotion.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('DETECTION', 'Detection', 'The user may always determine if a sensed character is force-sensitive when using Psychometry. They also may sense if any character uses the Dark Side of the Force.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('CLARITYPSYCH', 'Clarity', 'Spend [FP] to increase the clarity of a sensed image, sound, or emotion. This may be activated multiple times, increasing the clarity of a different sensed experience each time.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BEYONDVEIL', 'Beyond the Veil', 'The user may make a Perception check combined with a Psychometry Force power check. On success, the user senses the last moments of an engaged corpse or remains. The user suffers 1 conflict. The difficulty of the check is determined by the GM, based on the age of the remains.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('TRAILMEMORY', 'Trail of Memories', 'The user may spend [FP] to learn the direction of a sensed character if they left the immediate area. This may be activated multiple times, choosing a different sensed character each time. The Duration upgrade cannot be used to increase the duration of this effect.', 'PSYCHOMETRY', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, power_key = EXCLUDED.power_key;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('PSYCHBP', 'Psychometry Basic Power', 'Reaching out with their feelings, Force users may sense images, sounds, or emotions of people and events of the past. 
