[I]Modder[i] - The Modder shares the general split between personal gear and vehicle focus. Where they differ is that the Maintainer is less worried about perfection of gear and more about basic functionality and minor improvements in the moment', NULL, ARRAY['COOL', 'MECH', 'MELEE', 'PILOTPL'], '{"rows":[{"index":0,"cost":5,"talents":["SOLREP","FINETUN","FITES","GRIT"],"directions":[{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":false,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false},{"right":false,"down":true,"left":false,"up":false}]},{"index":1,"cost":10,"talents":["GEARHD","BADM","TOUGH","FICAL"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":false,"up":false},{"right":true,"down":true,"left":false,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":2,"cost":15,"talents":["CANNIB","FINETUN","CONT","GEARHD"],"directions":[{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":false,"up":true}]},{"index":3,"cost":20,"talents":["SOLREP","JULINE","MADMAI","FICAIMP"],"directions":[{"right":false,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":false,"up":true},{"right":true,"down":true,"left":true,"up":true},{"right":false,"down":true,"left":true,"up":true}]},{"index":4,"cost":25,"talents":["SOREIMP","FINTUNIMP","KIBA","DEDI"],"directions":[{"right":false,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":false,"up":true},{"right":true,"down":false,"left":false,"up":true},{"right":false,"down":false,"left":true,"up":true}]}]}'::jsonb, 'respec', false) ON CONFLICT (key, dataset_source) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, career_skill_keys = EXCLUDED.career_skill_keys, talent_tree = EXCLUDED.talent_tree;
